import os as _os
_os.environ.setdefault('KMP_DUPLICATE_LIB_OK', 'TRUE')
_os.environ.setdefault('OMP_NUM_THREADS', '4')
# Keep _os alive for _auto_install marker-file checks; it is a private
# alias and does not leak into the public API.

import subprocess as _sp
import sys as _sys

def _auto_install():
    """Auto-install all required packages. Skips already-installed ones.

    Cached: on second run, a marker file in the script directory lets the
    bootstrap return immediately without re-importing every module. Set
    CS_AUTO_INSTALL=0 to disable the marker and force a fresh check.
    """
    _required = {
        'torch': 'torch',
        'numpy': 'numpy',
        'PIL': 'pillow',
        'requests': 'requests',
        'networkx': 'networkx',
        'sympy': 'sympy',
        'bs4': 'beautifulsoup4',
        'pygame': 'pygame',
        'matplotlib': 'matplotlib',
        'psutil': 'psutil',
        'pytesseract': 'pytesseract',
        'fitz': 'pymupdf',
        'pyttsx3': 'pyttsx3',
        'tokenizers': 'tokenizers',
        'sounddevice': 'sounddevice',
        'whisper': 'openai-whisper',
    }
    _root = _os.path.dirname(_os.path.abspath(__file__))
    _marker = _os.path.join(_root, '.cs_deps_ok')
    if _os.environ.get('CS_AUTO_INSTALL', '1') != '0' and _os.path.isfile(_marker):
        return
    _missing = []
    for mod, pkg in _required.items():
        try:
            __import__(mod)
        except ImportError:
            _missing.append(pkg)
    if _missing:
        print(f"Installing missing packages: {', '.join(_missing)}")
        _sp.check_call(
            [_sys.executable, '-m', 'pip', 'install', '--quiet'] + _missing)
        print("Installation complete.")
    else:
        print("All dependencies already installed.")
    try:
        with open(_marker, 'w') as _f:
            _f.write('1')
    except Exception:
        pass

_auto_install()

def _write_launcher_bat():
    """Auto-generate launch.bat next to CS.py for double-click launching."""
    import os as _os
    _bat_path = _os.path.join(_os.path.dirname(_os.path.abspath(__file__)), 'launch.bat')
    _bat_content = r"""@echo off
title Consciousness Simulator - Launcher
echo ============================================================
echo   Consciousness Simulator - Auto Setup ^& Launch
echo ============================================================
echo.
echo Checking and installing required packages...
echo.
pip install torch torchvision torchaudio --quiet 2>nul
pip install numpy pillow requests networkx sympy beautifulsoup4 --quiet 2>nul
pip install pygame matplotlib psutil pytesseract pymupdf pyttsx3 tokenizers sounddevice openai-whisper --quiet 2>nul
echo.
echo All dependencies checked. Launching Consciousness Simulator...
echo ============================================================
echo.
python "%~dp0CS.py"
if %errorlevel% neq 0 (
    echo.
    echo ERROR: CS.py exited with error code %errorlevel%
    echo If Python was not found, install from python.org and add to PATH.
)
echo.
pause
"""
    try:
        with open(_bat_path, 'w') as _f:
            _f.write(_bat_content)
    except Exception:
        pass  # non-critical

_write_launcher_bat()
del _auto_install, _write_launcher_bat, _sp, _sys  # clean up namespace

