        self.perpetual_intelligence = PerpetualIntelligenceEngine(knowledge_dim=64, memory_size=256, device='cpu')
        self.hurdle_bypass = HurdleBypassEngine(device='cpu')
        # --- Substrate probe: bind to whatever instruments THIS host has ---
