            self.memory_list.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)
            sb3.pack(side=tk.RIGHT, fill=tk.Y)
            self.memory_list.bind("<<ListboxSelect>>", self.show_memory_details)
            mem_right = tk.Frame(mem_tab, bg=BG)
