def _build_wave31_barrier_catalog():
    catalog = []
    for d_idx, dim in enumerate(CS_WAVE31_BARRIER_DIMENSIONS):
        for s_idx, sub in enumerate(CS_WAVE31_BARRIER_SUBSYSTEMS):
            for r_idx, resolve in enumerate(CS_WAVE31_BARRIER_RESOLVES):
                h_idx = (d_idx * 3 + s_idx * 7 + r_idx * 11) % len(CS_WAVE31_BARRIER_HURDLES)
                hurdle = CS_WAVE31_BARRIER_HURDLES[h_idx]
                barrier_text = (
                    f"[{dim}] the {sub} hits a {hurdle} "
                    f"(resolve via {resolve})"
                )
                catalog.append({
                    'id': len(catalog) + 1,
                    'dimension': dim,
                    'subsystem': sub,
                    'hurdle': hurdle,
                    'resolve_kind': resolve,
                    'barrier': barrier_text,
                    'active': True,
                    'resolved_hits': 0,
                })
    return catalog


CS_WAVE31_BARRIERS = _build_wave31_barrier_catalog()


# -----------------------------------------------------------------------------
# HARD-CODED BYPASS FUNCTIONS — every resolve_kind is an engineering action
# -----------------------------------------------------------------------------
# Each function treats its barrier as a live engineering hurdle and applies a
# safe, reversible, runtime-level bypass.  None of them assume the target
# subsystem exists; they all fall back to setting a flag that the rest of the
# runtime can read on its next decision.


def _wave31_bypass_instrumentation(sim, barrier):
    """Measure the barrier and record it; observation precedes intervention."""
    try:
        sim._wave31_instrumentation_hits = getattr(sim, '_wave31_instrumentation_hits', 0) + 1
        sim._wave31_last_baseline = _record_baseline()
        log = getattr(sim, '_wave31_resolve_log', deque(maxlen=500))
        log.append(f"#{barrier['id']} [{barrier['dimension']}/{barrier['subsystem']}] instrumented")
        sim._wave31_resolve_log = log
    except Exception:
        pass


def _wave31_bypass_quantization(sim, barrier):
    """Push weights/activations toward lower precision for the target subsystem."""
    try:
        sim._wave31_quantize_hits = getattr(sim, '_wave31_quantize_hits', 0) + 1
        CONFIG['quantization_aware'] = True
        if barrier['subsystem'] == 'token_pipeline':
            sim._wave31_token_quantize = True
        elif barrier['subsystem'] == 'kv_cache_manager':
            sim._wave31_kv_cache_compress = True
        elif barrier['subsystem'] == 'ffn_expert_block':
            sim._wave31_ffn_quantize = True
    except Exception:
        pass


def _wave31_bypass_pruning(sim, barrier):
    """Remove low-salience parts of the target subsystem."""
    try:
        sim._wave31_prune_hits = getattr(sim, '_wave31_prune_hits', 0) + 1
        CONFIG['aggressive_pruning'] = True
        CONFIG['extreme_optimization'] = True
        sim._wave31_prune_target = barrier['subsystem']
    except Exception:
        pass


def _wave31_bypass_caching(sim, barrier):
    """Enlarge or invalidate caches for the target subsystem."""
    try:
        sim._wave31_cache_hits = getattr(sim, '_wave31_cache_hits', 0) + 1
        if barrier['subsystem'] == 'kv_cache_manager':
            CONFIG['cache_size'] = min(int(CONFIG.get('cache_size', 1000) * 1.05), 5000)
            sim._wave31_kv_cache_refresh = True
        else:
            CONFIG['history_limit'] = min(int(CONFIG.get('history_limit', 200) * 1.05), 1000)
    except Exception:
        pass


def _wave31_bypass_compilation(sim, barrier):
    """Signal that the target subsystem should be JIT/flash compiled."""
    try:
        sim._wave31_compile_hits = getattr(sim, '_wave31_compile_hits', 0) + 1
        CONFIG['use_flash_attention'] = True
        CONFIG['memory_efficient_attention'] = True
        sim._wave31_compile_target = barrier['subsystem']
    except Exception:
        pass


def _wave31_bypass_distillation(sim, barrier):
    """Compress knowledge from the target subsystem back into the model."""
    try:
        sim._wave31_distill_hits = getattr(sim, '_wave31_distill_hits', 0) + 1
        sim._wave31_distill_target = barrier['subsystem']
        de = getattr(sim, 'dream_engine', None)
        if de is not None:
            sim._wave31_replay_dream = True
    except Exception:
        pass


def _wave31_bypass_routing(sim, barrier):
    """Route workload toward the cognitive domain best suited to the subsystem."""
    try:
        sim._wave31_route_hits = getattr(sim, '_wave31_route_hits', 0) + 1
        sim._wave31_route_target = barrier['subsystem']
        if barrier['subsystem'] == 'symbolic_integrator':
            sim._wave31_symbolic_route_boost = getattr(sim, '_wave31_symbolic_route_boost', 0.0) + 0.05
        elif barrier['subsystem'] == 'self_model':
            sim._wave31_self_model_route_boost = getattr(sim, '_wave31_self_model_route_boost', 0.0) + 0.05
    except Exception:
        pass


def _wave31_bypass_indexing(sim, barrier):
    """Build or refresh a fast index for the target subsystem."""
    try:
        sim._wave31_index_hits = getattr(sim, '_wave31_index_hits', 0) + 1
        if barrier['subsystem'] == 'knowledge_graph':
            sim._wave31_reindex_knowledge = True
        elif barrier['subsystem'] == 'token_pipeline':
            sim._wave31_reindex_tokens = True
        elif barrier['subsystem'] == 'self_model':
            sim._wave31_reindex_self_model = True
    except Exception:
        pass


def _wave31_bypass_rehearsal(sim, barrier):
    """Replay recent experience for the target subsystem."""
    try:
        sim._wave31_rehearsal_hits = getattr(sim, '_wave31_rehearsal_hits', 0) + 1
        mem = getattr(sim, 'memory', None)
        if mem is not None:
            consolidate = getattr(mem, 'consolidate', None)
            if callable(consolidate):
                try:
                    consolidate(n_replays=1)
                except Exception:
                    pass
        sim._wave31_rehearsal_target = barrier['subsystem']
    except Exception:
        pass


def _wave31_bypass_resonance(sim, barrier):
    """Boost cross-module coupling for the target subsystem."""
    try:
        sim._wave31_resonance_hits = getattr(sim, '_wave31_resonance_hits', 0) + 1
        CONFIG['phi_weight'] = min(CONFIG.get('phi_weight', 0.4) + 0.01, 1.0)
        sim._wave31_resonance_target = barrier['subsystem']
    except Exception:
        pass


_BARRIER_RESOLVE_DISPATCH = {
    'instrumentation': _wave31_bypass_instrumentation,
    'quantization': _wave31_bypass_quantization,
    'pruning': _wave31_bypass_pruning,
    'caching': _wave31_bypass_caching,
    'compilation': _wave31_bypass_compilation,
    'distillation': _wave31_bypass_distillation,
    'routing': _wave31_bypass_routing,
    'indexing': _wave31_bypass_indexing,
    'rehearsal': _wave31_bypass_rehearsal,
    'resonance': _wave31_bypass_resonance,
}


class ThirtyFirstWaveBarrierEngine:
    """Treat the 1,000 surpass barriers as engineering items to be coded around.

    Each step selects the next active barrier and applies the hard-coded bypass
    for its resolve_kind.  Runtime hurdles (CPU fallback, high memory, low phi)
    are detected and used to prioritize matching barriers, so the engine treats
    every block as an obstacle to be engineered around rather than accepted.
    """

    def __init__(self, sim):
        self._sim = sim
        self._catalog = CS_WAVE31_BARRIERS
        self._by_dimension = {}
        for i, b in enumerate(self._catalog):
            self._by_dimension.setdefault(b['dimension'], []).append(i)
        self._next_index = 0
        self._rng = random.Random(hash(id(sim)) + 3131313131)
        self._resolved_count = 0
        self._running = False
        self._thread = None

    def start(self):
        if self._running:
            return
        self._running = True
        self._thread = threading.Thread(target=self._loop, daemon=True, name='CS_Wave31Barrier')
        self._thread.start()

    def stop(self):
        self._running = False

    def _loop(self):
        while self._running:
            try:
                sim = self._sim
                if hasattr(sim, 'running') and sim.running is False:
                    break
                self.step()
            except Exception:
                pass
            time.sleep(1.0)

    def _detect_priority_dimension(self):
        """Map live runtime pressure to the most relevant surpass dimension."""
        try:
            sim = self._sim
            if getattr(sim, 'device', None) is not None and sim.device.type == 'cpu':
                return 'inference_throughput'
            if torch.cuda.is_available() and getattr(sim, 'device', None) is not None and sim.device.type == 'cuda':
                total = torch.cuda.get_device_properties(sim.device).total_memory
                if total > 0:
                    mem = torch.cuda.memory_allocated(sim.device) / total
                    if mem > 0.8:
                        return 'context_window_efficiency'
            if getattr(sim, 'phi', 0.0) < 0.2:
                return 'causal_fidelity'
            if getattr(sim, 'C', 0.0) < 0.3:
                return 'self_model_depth'
            if getattr(sim, '_correlation_heat', 0.0) < 0.05:
                return 'multimodal_grounding'
        except Exception:
            pass
        return None

    def step(self):
        try:
            s = self._sim
            if not self._catalog:
                return
            # Prefer a barrier that matches a live runtime hurdle.
            priority_dim = self._detect_priority_dimension()
            if priority_dim and priority_dim in self._by_dimension:
                priority_pool = self._by_dimension[priority_dim]
                self._next_index = self._rng.choice(priority_pool)
            barrier = self._catalog[self._next_index]
            self._next_index = (self._next_index + 1) % len(self._catalog)
            barrier['resolved_hits'] += 1
            self._resolved_count += 1
            s._wave31_active_barrier = barrier
            s._wave31_resolved_count = self._resolved_count
            s._wave31_active_dimension = barrier['dimension']
            s._wave31_active_subsystem = barrier['subsystem']
            attr = f"_wave31_resolve_{barrier['resolve_kind']}"
            current = getattr(s, attr, 0)
            setattr(s, attr, current + 1)
            # Apply the hard-coded engineering bypass for this resolve kind.
            resolver = _BARRIER_RESOLVE_DISPATCH.get(
                barrier['resolve_kind'], _wave31_bypass_instrumentation)
            resolver(s, barrier)
        except Exception:
            pass

    def get_status(self):
        return {
            'total_barriers': len(self._catalog),
            'resolved_count': self._resolved_count,
            'next_index': self._next_index,
            'active_barrier_id': (
                self._catalog[(self._next_index - 1) % len(self._catalog)]['id']
                if self._catalog and self._resolved_count > 0 else 1
            ),
            'active_dimension': getattr(self._sim, '_wave31_active_dimension', None),
            'active_subsystem': getattr(self._sim, '_wave31_active_subsystem', None),
            'thread_alive': bool(self._thread and self._thread.is_alive()),
        }


