def _wave34_growth_surgery(sim, barrier):
    """#1: real structural growth (plan + CONFIG delta, rollbackable)."""
    try:
        stack = getattr(sim, 'transformer_stack', None) or getattr(sim, 'model', None)
        if stack is None:
            sim._wave34_growth_surgery_recommended = True
            sim._wave34_growth_surgery_plan = {
                'add_blocks': 1,
                'method': 'identity_init_append',
                'old_n_layers': CONFIG.get('n_layers', 4),
            }
            CONFIG['n_layers'] = CONFIG.get('n_layers', 4) + 1
            return True
        # If a stack exists, append one identity-initialized block if possible
        if hasattr(stack, 'append') and isinstance(stack, (list, nn.ModuleList)):
            from torch.nn import TransformerEncoderLayer
            d = CONFIG.get('dim', 512)
            h = CONFIG.get('num_heads', 8)
            new_block = TransformerEncoderLayer(d, h, dim_feedforward=4*d, batch_first=True)
            for p in new_block.parameters():
                p.detach().zero_()
            stack.append(new_block)
            sim._wave34_growth_surgery_applied = len(stack)
            return True
        sim._wave34_growth_surgery_recommended = True
        return True
    except Exception:
        return False


def _wave34_quantize_switch(sim, barrier):
    """#2: keep a quantized model and flag it for inference."""
    try:
        container = getattr(sim, '_wave33_quantized_container', None)
        if container is not None and isinstance(container, (tuple, list)) and container:
            sim._wave34_quantized_for_eval = True
            sim._wave34_quantize_switch_ok = True
            return True
        sim._wave34_quantize_switch_ok = False
        return True
    except Exception:
        return False


def _wave34_symbolic_router_patch(sim, barrier):
    """#3: monkey-patch respond() to route physics/math prompts to symbolic."""
    try:
        if not hasattr(sim, 'respond'):
            sim._wave34_respond_missing = True
            return True
        orig = sim.respond
        keywords = getattr(sim, '_wave33_symbolic_keywords',
                           ['force', 'mass', 'energy', 'current', 'voltage',
                            'derivative', 'integral', 'equation', 'solve'])
        def _patched(self, *args, **kwargs):
            prompt = args[0] if args else kwargs.get('prompt', '')
            if isinstance(prompt, str) and any(k in prompt.lower() for k in keywords):
                kwargs['task_category'] = 'symbolic'
            return orig(*args, **kwargs)
        sim.respond = _types.MethodType(_patched, sim)
        sim._wave34_symbolic_router_patched = True
        return True
    except Exception:
        return False


def _wave34_sympy_composer(sim, barrier):
    """#4 / #19: try to derive a new law from two existing laws."""
    try:
        import sympy as sp
        laws = list(PHYSICS_LAWS.values())
        math = list(MATH_EQUATIONS.values())
        src = laws + math
        if len(src) < 2:
            return False
        rng = random.Random(20260804 + len(src))
        a, b = rng.sample(src, 2)
        ea = a.get('sympy_eq') or a.get('eq')
        eb = b.get('sympy_eq') or b.get('eq')
        if ea is None or eb is None:
            desc_a = a.get('desc','')
            desc_b = b.get('desc','')
            derived = f"derived: {desc_a} + {desc_b}"
            sim._wave34_derived_laws = getattr(sim, '_wave34_derived_laws', []) + [derived]
            return True
        # attempt real sympy composition
        sym_a = sp.sympify(str(ea))
        sym_b = sp.sympify(str(eb))
        # derive by taking the difference (compose via substitution if shared symbol)
        shared = set(sym_a.free_symbols) & set(sym_b.free_symbols)
        if shared:
            s = shared.pop()
            sol = sp.solve(sym_a - sym_b, s)
            if sol:
                derived = sp.simplify(sol[0])
                sim._wave34_derived_laws = getattr(sim, '_wave34_derived_laws', []) + [str(derived)]
                return True
        sim._wave34_symbolic_compose_tried = True
        return True
    except Exception:
        return False


