def _wave34_adversarial_perturb(sim, barrier):
    """#8: perturb the prompt and check output consistency."""
    try:
        base = "adversarial perturbation probe"
        perturb = base.upper()
        with torch.no_grad():
            toks1 = sim.simple_tokenizer(base)
            out1, *_ = sim(toks1, task_category='adversarial_probe')
            toks2 = sim.simple_tokenizer(perturb)
            out2, *_ = sim(toks2, task_category='adversarial_probe')
        if not torch.isfinite(out1).all() or not torch.isfinite(out2).all():
            sim._wave34_adversarial_perturb_passed = False
            return True
        if out1.dim() > 1 and out2.dim() > 1:
            t1 = out1.view(-1).argmax()
            t2 = out2.view(-1).argmax()
            sim._wave34_adversarial_perturb_passed = bool(int(t1) == int(t2))
        else:
            sim._wave34_adversarial_perturb_passed = True
        return True
    except Exception:
        return False


