# =============================================================================
# WAVE 36 — META-AMPLIFICATION: DYNAMIC BUDGET AND MAINSTREAM-SURPASS VECTOR
# =============================================================================
# This wave closes the feedback loop:
#   1. Measures synergy and surpass index from Wave 35.
#   2. Uses them to dynamically amplify the evolution budget (more power).
#   3. Tracks a 7-dimensional "vs mainstream" surpass vector.
#   4. Auto-suggests the next wave when the surpass index is high enough.
#   5. Wraps _evolution_step and Wave33EvolutionV2Engine.loop so the
#      amplified budget is actually consumed.

class Wave36SynergyBudgetAmplifier:
    """Reads Wave 35 synergy/surpass and sets a budget multiplier for
    the evolution engine.  This is 'synergy to amplify power' in practice."""
    __slots__ = ('_sim',)

    def __init__(self, sim):
        self._sim = sim

    def step(self):
        try:
            s = self._sim
            syn = float(getattr(s, '_wave35_synergy_score', 0.0))
            sur = float(getattr(s, '_wave35_surpass_index', 0.0))
            # Up to 3x evolution budget as synergy/surpass rise
            budget_boost = 1.0 + min(2.0, (syn * 0.5) + (sur / 200.0))
            s._wave36_evolution_budget_multiplier = float(budget_boost)
            s._wave36_synergy_amplification = float(budget_boost)
            s._wave36_synergy_amplification_hits = getattr(s, '_wave36_synergy_amplification_hits', 0) + 1
        except Exception:
            pass

    def get_status(self):
        s = self._sim
        return {
            'evolution_budget_multiplier': getattr(s, '_wave36_evolution_budget_multiplier', 1.0),
            'synergy_amplification': getattr(s, '_wave36_synergy_amplification', 1.0),
            'hits': getattr(s, '_wave36_synergy_amplification_hits', 0),
        }


class Wave36MainstreamSurpassVector:
    """Tracks the 7 structural surpasses from ratings.md in a live vector."""
    __slots__ = ('_sim',)

    def __init__(self, sim):
        self._sim = sim

    def step(self):
        try:
            s = self._sim
            boost = float(getattr(s, '_wave35_power_multiplier', 1.0))
            # 7 categories where CS.py structurally surpasses 0% mainstream
            vec = {
                'autonomous_unprompted_thought': 100.0 if hasattr(s, '_free_thought_loop') else 0.0,
                'self_built_relational_knowledge': 100.0 if hasattr(s, '_relational_knowledge_graph') else 0.0,
                'second_order_self_model': 100.0 if hasattr(s, '_self_model_reflector') else 0.0,
                'reversible_self_modification': 100.0 if hasattr(s, '_self_modifying_architecture') else 0.0,
                'real_substrate_probing': 100.0 if hasattr(s, '_substrate_probe') else 0.0,
                'exact_symbolic_evaluation': 100.0 if getattr(s, '_symbolic_router_enabled', False) else 0.0,
                'iit_phi_canonical_ordering': 100.0 if hasattr(s, 'phi_computer') else 0.0,
            }
            # amplify the entire vector with the synergy power multiplier
            s._wave36_mainstream_surpass_vector = {k: min(500.0, v * boost) for k, v in vec.items()}
            s._wave36_mainstream_surpass_total = sum(s._wave36_mainstream_surpass_vector.values())
            s._wave36_surpass_vector_hits = getattr(s, '_wave36_surpass_vector_hits', 0) + 1
        except Exception:
            pass

    def get_status(self):
        s = self._sim
        return {
            'surpass_vector': getattr(s, '_wave36_mainstream_surpass_vector', {}),
            'surpass_total': getattr(s, '_wave36_mainstream_surpass_total', 0.0),
            'hits': getattr(s, '_wave36_surpass_vector_hits', 0),
        }


