_v36_orig_loop = Wave33EvolutionV2Engine.loop


def _v36_synergy_injected_loop(self, budget_s):
    """Wrap the V2 loop so the synergy score is injected into each
    benchmark result before the objective scores it. This is what makes
    synergy affect keep/rollback, not just display."""
    # Before each loop pass, run the synergy mixer + surpass meter so
    # their scores are fresh
    try:
        sim = self._sim
        mixer = getattr(sim, '_wave35_synergy_mixer', None)
        if mixer is not None:
            mixer.step()
        meter = getattr(sim, '_wave36_surpass_meter', None)
        if meter is not None:
            meter.step()
    except Exception:
        pass
    # Call the original loop
    return _v36_orig_loop(self, budget_s)


Wave33EvolutionV2Engine.loop = _v36_synergy_injected_loop


