def _wave37_math_benchmark(sim, barrier):
    """B. math — set a target and run a tiny symbolic probe."""
    try:
        sim._wave37_math_benchmark_active = True
        sim._wave37_math_target = 90.0  # %
        score = 0.0
        total = 0
        for key, eq in list(MATH_EQUATIONS.items())[:8]:
            q = f"What is {key.replace('_',' ')}?"
            a = sim.respond(q, max_tokens=16)
            desc = eq.get('desc', '') or eq.get('name', '')
            if desc and desc in a:
                score += 1.0
            total += 1
        sim._wave37_math_score = (score / max(1, total)) * 100.0
        return True
    except Exception:
        return False


