_wave37_prev_build_barrier_resolvers = _build_barrier_resolvers


def _wave37_build_barrier_resolvers(sim):
    r = _wave37_prev_build_barrier_resolvers(sim)
    wave37_resolvers = [
        Wave37RatingsResolver(sim, kind, risk=_WAVE37_RISKS.get(kind, 'low'))
        for kind in _WAVE37_ACTIONS.keys()
    ]
    for k in r:
        r[k].extend(wave37_resolvers)
    # priority gaps
    r['oom_risk'].insert(0, Wave37RatingsResolver(sim, 'memory_footprint', 'high'))
    r['latency_breach'].insert(0, Wave37RatingsResolver(sim, 'throughput', 'medium'))
    r['corpus_starved'].insert(0, Wave37RatingsResolver(sim, 'synthetic_corpus', 'low'))
    r['loss_plateau'].insert(0, Wave37RatingsResolver(sim, 'data_curation', 'low'))
    r['benchmark_regression'].insert(0, Wave37RatingsResolver(sim, 'ppl_target', 'medium'))
    r['vocab_saturated'].insert(0, Wave37RatingsResolver(sim, 'vocab', 'high'))
    r['context_exhausted'].insert(0, Wave37RatingsResolver(sim, 'context_window', 'high'))
    r['subtree_silent_failure'].insert(0, Wave37RatingsResolver(sim, 'hallucination_detect', 'low'))
    return r


_build_barrier_resolvers = _wave37_build_barrier_resolvers


