# =============================================================================
# WAVE 39 — SELF-OUTSCALING: 10× ADDITIONS IN POWER
# =============================================================================
# The goal is for CS.py to outscale itself.  This wave adds 10 compound
# power-amplifier resolvers (each ~1.25×) and a meter that multiplies them,
# capped at a 10× total power multiplier.  The evolution step budget and
# the Wave36 loop wrapper both read the live compound power, so the engine
# literally runs up to 10× harder when all amplifiers are active.

_WAVE39_POWER_FACTORS = {
    'data_10x': 1.25,
    'params_10x': 1.25,
    'context_10x': 1.25,
    'throughput_10x': 1.25,
    'synergy_10x': 1.25,
    'surpass_10x': 1.25,
    'compute_10x': 1.25,
    'memory_10x': 1.25,
    'training_10x': 1.25,
    'auto_10x': 1.25,
}


class Wave39CompoundPowerMeter:
    """Multiplies all active Wave39 power factors into a single 10x cap."""
    __slots__ = ('_sim',)

    def __init__(self, sim):
        self._sim = sim

    def step(self):
        try:
            s = self._sim
            product = 1.0
            active = 0
            for kind, factor in _WAVE39_POWER_FACTORS.items():
                if getattr(s, f'_wave39_{kind}_active', False):
                    product *= factor
                    active += 1
            # self-reinforcement: if the exceed_all score improved, add a bonus
            prev = float(getattr(s, '_wave39_prev_exceed_score', 0.0))
            curr = float(getattr(s, '_wave38_exceed_all_score', 0.0))
            if curr > prev:
                product *= 1.1
            s._wave39_prev_exceed_score = curr
            s._wave39_compound_power = float(product)
            s._wave39_power_10x = float(min(10.0, product))
            s._wave39_power_amplifiers_active = active
            s._wave39_power_meter_hits = getattr(s, '_wave39_power_meter_hits', 0) + 1
        except Exception:
            pass

    def get_status(self):
        s = self._sim
        return {
            'compound_power': getattr(s, '_wave39_compound_power', 1.0),
            'power_10x': getattr(s, '_wave39_power_10x', 1.0),
            'amplifiers_active': getattr(s, '_wave39_power_amplifiers_active', 0),
            'hits': getattr(s, '_wave39_power_meter_hits', 0),
        }


class Wave39PowerResolver(_ResolverBase):
    """One of the 10 power-amplifier resolvers."""
    __slots__ = ('_kind',)

    def __init__(self, sim, kind, risk='low'):
        super().__init__(sim, risk)
        self._kind = kind

    def name(self):
        return f"Wave39Power{self._kind.title().replace('_','')}Resolver"

    def apply(self, sim, barrier):
        try:
            attr = f'_wave39_{self._kind}_active'
            if getattr(sim, attr, False):
                return True  # already active, no-op is fine
            setattr(sim, attr, True)
            sim._wave39_power_activations = getattr(sim, '_wave39_power_activations', 0) + 1
            return True
        except Exception:
            return False


class Wave39SelfOutscaleResolver(_ResolverBase):
    """When current state beats previous state, escalate power."""
    __slots__ = ()

    def __init__(self, sim):
        super().__init__(sim, 'high')

    def apply(self, sim, barrier):
        try:
            prev = float(getattr(sim, '_wave39_prev_outscale_score', 0.0))
            curr = float(getattr(sim, '_wave38_exceed_all_score', 0.0))
            mult = float(getattr(sim, '_wave39_self_outscale_multiplier', 1.0))
            if curr > prev:
                mult = min(10.0, mult * 1.25)
                sim._wave39_outscale_improved = True
            else:
                sim._wave39_outscale_improved = False
            sim._wave39_prev_outscale_score = curr
            sim._wave39_self_outscale_multiplier = mult
            sim._wave39_self_outscale_active = True
            return True
        except Exception:
            return False


# ---------------------------------------------------------------------------
# Hook power resolvers into the evolution map
