_wave39_prev_build_barrier_resolvers = _build_barrier_resolvers


def _wave39_build_barrier_resolvers(sim):
    r = _wave39_prev_build_barrier_resolvers(sim)
    for kind in _WAVE39_POWER_FACTORS.keys():
        r['loss_plateau'].insert(0, Wave39PowerResolver(sim, kind, 'low'))
    for k in r:
        r[k].append(Wave39SelfOutscaleResolver(sim))
    return r


_build_barrier_resolvers = _wave39_build_barrier_resolvers


