_evolution_step_outscale_prev = _evolution_step


def _evolution_step_10x(sim):
    """_evolution_step multiplied by the live compound power up to 10x."""
    eng = getattr(sim, '_evolution_engine', None)
    if eng is None or not eng._enabled:
        return
    try:
        power = float(getattr(sim, '_wave39_power_10x', 1.0))
        power = min(10.0, max(0.1, power))
        eng.loop(budget_s=0.1 * power)
    except Exception:
        pass


_evolution_step = _evolution_step_10x


