_wave40_prev_build = _build_barrier_resolvers


def _wave40_build_barrier_resolvers(sim):
    r = _wave40_prev_build(sim)
    # Context extension for context_exhausted
    r['context_exhausted'].insert(0, Wave40ContextExtensionResolver(sim))
    # Training convergence for loss_plateau and corpus_starved
    r['loss_plateau'].insert(0, Wave40TrainingConvergenceResolver(sim))
    r['corpus_starved'].insert(0, Wave40TrainingConvergenceResolver(sim))
    # DPO for corpus_starved and loss_plateau
    r['corpus_starved'].insert(1, Wave40DPOResolver(sim))
    r['loss_plateau'].insert(1, Wave40DPOResolver(sim))
    # Concurrency fix for subtree_silent_failure and dead_component
    r['subtree_silent_failure'].insert(0, Wave40ConcurrencyLockResolver(sim))
    r['dead_component'].insert(0, Wave40ConcurrencyLockResolver(sim))
    # Corpus expansion for corpus_starved
    r['corpus_starved'].insert(0, Wave40CorpusExpansionResolver(sim))
    # Benchmark verifier for all barriers
    for k in r:
        r[k].append(Wave40BenchmarkVerifierResolver(sim))
    return r


