# =============================================================================
# WAVE 41 — REAL-WORK ORCHESTRATOR (execute the Wave40 mechanisms)
# =============================================================================
# Wave 40 added verified real-work resolvers.  Wave 41 doesn't add more
# resolvers; it runs the existing ones in a deterministic pipeline with
# before/after benchmarks and verify-before-keep rollback.  This is the
# fastest path from "wired" to "actually trained".
#
# Set CS_AUTO_REAL_WORK=0 to skip the pipeline; it defaults to enabled.

class Wave41RealWorkOrchestrator:
    """Runs the Wave40 real-work resolvers as a single, verified pipeline."""
    __slots__ = ('_sim', '_done')

    def __init__(self, sim):
        self._sim = sim
        self._done = False

    def step(self):
        if self._done or os.environ.get('CS_AUTO_REAL_WORK', '1') == '0':
            return
        s = self._sim
        try:
            pipeline = [
                (Wave40CorpusExpansionResolver, {'type': 'corpus_starved'}),
                (Wave40ContextExtensionResolver, {'type': 'context_exhausted'}),
                (Wave40ConcurrencyLockResolver, {'type': 'subtree_silent_failure'}),
                (Wave40TrainingConvergenceResolver, {'type': 'loss_plateau'}),
                (Wave40DPOResolver, {'type': 'benchmark_regression'}),
                (Wave40BenchmarkVerifierResolver, {'type': 'benchmark_regression'}),
            ]
            results = []
            for cls, barrier in pipeline:
                try:
                    resolver = cls(s)
                    ckpt = CheckpointManager(s)
                    ckpt.snapshot(label=f'wave41_{resolver.name()}')

                    before = s.run_internal_benchmark(n_lines=2, verbose=False)
                    before_loss = before.get('mean_loss')

                    ok = resolver.apply(s, barrier)

                    after = s.run_internal_benchmark(n_lines=2, verbose=False)
                    after_loss = after.get('mean_loss')

                    improved = (ok and after_loss is not None and
                                (before_loss is None or after_loss < before_loss * 0.99))
                    if improved:
                        results.append((resolver.name(), 'kept', before_loss, after_loss))
                    else:
                        ckpt.restore()
                        results.append((resolver.name(), 'rolled_back', before_loss, after_loss))
                except Exception as e:
                    results.append((cls.__name__, 'error', None, repr(e)))

            s._wave41_real_work_results = results
            s._wave41_real_work_done = True
            s._wave41_real_work_kept = sum(1 for r in results if r[1] == 'kept')
            s._wave41_real_work_rolled = sum(1 for r in results if r[1] == 'rolled_back')
        except Exception as e:
            s._wave41_real_work_error = repr(e)
            s._wave41_real_work_done = True
        self._done = True

    def get_status(self):
        s = self._sim
        return {
            'done': getattr(s, '_wave41_real_work_done', False),
            'kept': getattr(s, '_wave41_real_work_kept', 0),
            'rolled_back': getattr(s, '_wave41_real_work_rolled', 0),
            'error': getattr(s, '_wave41_real_work_error', None),
            'results': getattr(s, '_wave41_real_work_results', []),
        }


