# Flatten GENRE_TAXONOMY into a reverse-lookup: sub_genre -> (category, genre)
GENRE_REVERSE_LOOKUP = {}
for _cat, _genres in GENRE_TAXONOMY.items():
    for _genre, _subgenres in _genres.items():
        for _sg in _subgenres:
            GENRE_REVERSE_LOOKUP[_sg] = (_cat, _genre)

# Build a keyword index for genre routing: keyword -> sub_genre
GENRE_KEYWORD_INDEX = {}
for _sg in GENRE_REVERSE_LOOKUP:
    _parts = _sg.split('_')
    for _p in _parts:
        if _p not in GENRE_KEYWORD_INDEX:
            GENRE_KEYWORD_INDEX[_p] = _sg
    GENRE_KEYWORD_INDEX[_sg] = _sg


def route_to_genre(query, fallback='general'):
    """Route a natural-language query string to the best-matching sub-genre.
    Uses keyword overlap with GENRE_KEYWORD_INDEX for O(1) lookup per token."""
    ql = (query or '').lower()
    if not ql:
        return fallback
    best = None
    best_score = 0
    for kw, sg in GENRE_KEYWORD_INDEX.items():
        if kw in ql:
            score = len(kw)
            if score > best_score:
                best_score = score
                best = sg
    return best or fallback


def route_to_category(query, fallback='general'):
    """Route a query to its top-level category using GENRE_TAXONOMY."""
    sg = route_to_genre(query, None)
    if sg and sg in GENRE_REVERSE_LOOKUP:
        return GENRE_REVERSE_LOOKUP[sg][0]
    return fallback


