# ---------------------------------------------------------------------------
# DICTIONARY_ROUTES — O(1) lookup routing system
#
# Builds a flat keyword -> entry index from SUPER_INTELLIGENCE_LIBRARY.
# Every key, related term, and genre keyword maps to the library entry.
# Lookup is O(1) hash table access — no bottleneck.
# ---------------------------------------------------------------------------
DICTIONARY_ROUTES = {}
DICTIONARY_ROUTES_BY_GENRE = {}
DICTIONARY_ROUTES_BY_CATEGORY = {}

for _key, _entry in SUPER_INTELLIGENCE_LIBRARY.items():
    # Direct key lookup
    DICTIONARY_ROUTES[_key] = _key
    # Also index by words in the key
    for _word in _key.split('_'):
        if _word not in DICTIONARY_ROUTES:
            DICTIONARY_ROUTES[_word] = _key
    # Index by related terms
    for _rel in _entry.get('related', ()):
        DICTIONARY_ROUTES[_rel] = _rel if _rel in SUPER_INTELLIGENCE_LIBRARY else _key
    # Index by genre
    _sg = _entry.get('genre', '')
    if _sg:
        if _sg not in DICTIONARY_ROUTES_BY_GENRE:
            DICTIONARY_ROUTES_BY_GENRE[_sg] = []
        DICTIONARY_ROUTES_BY_GENRE[_sg].append(_key)
    # Index by category
    _cat = _entry.get('category', '')
    if _cat:
        if _cat not in DICTIONARY_ROUTES_BY_CATEGORY:
            DICTIONARY_ROUTES_BY_CATEGORY[_cat] = []
        DICTIONARY_ROUTES_BY_CATEGORY[_cat].append(_key)


def dict_lookup(query):
    """O(1) dictionary route lookup. Returns the library entry or None."""
    if not query:
        return None
    ql = query.lower().strip()
    # Direct lookup
    if ql in DICTIONARY_ROUTES:
        target = DICTIONARY_ROUTES[ql]
        if target in SUPER_INTELLIGENCE_LIBRARY:
            return SUPER_INTELLIGENCE_LIBRARY[target]
    # Try with underscores
    ql_u = ql.replace(' ', '_')
    if ql_u in DICTIONARY_ROUTES:
        target = DICTIONARY_ROUTES[ql_u]
        if target in SUPER_INTELLIGENCE_LIBRARY:
            return SUPER_INTELLIGENCE_LIBRARY[target]
    # Route by genre
    sg = route_to_genre(ql, None)
    if sg and sg in DICTIONARY_ROUTES_BY_GENRE:
        keys = DICTIONARY_ROUTES_BY_GENRE[sg]
        if keys:
            return SUPER_INTELLIGENCE_LIBRARY[keys[0]]
    return None


def dict_lookup_related(query, max_results=5):
    """Look up a term and return related entries. O(1) per related key."""
    entry = dict_lookup(query)
    if not entry:
        return []
    results = []
    for rel_key in entry.get('related', ()):
        if rel_key in SUPER_INTELLIGENCE_LIBRARY:
            results.append(SUPER_INTELLIGENCE_LIBRARY[rel_key])
            if len(results) >= max_results:
                break
    return results


def dict_lookup_genre(genre_name):
    """Return all library entries for a given sub-genre. O(1) lookup."""
    keys = DICTIONARY_ROUTES_BY_GENRE.get(genre_name, [])
    return [SUPER_INTELLIGENCE_LIBRARY[k] for k in keys if k in SUPER_INTELLIGENCE_LIBRARY]


def dict_lookup_category(category_name):
    """Return all library entries for a given category. O(1) lookup."""
    keys = DICTIONARY_ROUTES_BY_CATEGORY.get(category_name, [])
    return [SUPER_INTELLIGENCE_LIBRARY[k] for k in keys if k in SUPER_INTELLIGENCE_LIBRARY]


# ---------------------------------------------------------------------------
# CORRELATIVE_MATRIX — cross-domain correlation strengths
#
# A sparse matrix of genre-to-genre correlation strengths (0.0 to 1.0).
# Built from explicit related-links in SUPER_INTELLIGENCE_LIBRARY plus
# shared-category and shared-genre bonuses.  Used for:
#   - Cross-domain knowledge activation
#   - Suggesting related concepts during reasoning
#   - Computing synergy scores between subsystems
#
# Stored as a dict-of-dicts for O(1) lookup without materializing a
# full N×N matrix (which would be large and mostly zeros).
# ---------------------------------------------------------------------------
CORRELATIVE_MATRIX = {}

# Build from related links
for _key, _entry in SUPER_INTELLIGENCE_LIBRARY.items():
    _sg1 = _entry.get('genre', 'unknown')
    for _rel in _entry.get('related', ()):
        if _rel in SUPER_INTELLIGENCE_LIBRARY:
            _sg2 = SUPER_INTELLIGENCE_LIBRARY[_rel].get('genre', 'unknown')
            if _sg1 not in CORRELATIVE_MATRIX:
                CORRELATIVE_MATRIX[_sg1] = {}
            if _sg2 not in CORRELATIVE_MATRIX[_sg1]:
                CORRELATIVE_MATRIX[_sg1][_sg2] = 0.0
            CORRELATIVE_MATRIX[_sg1][_sg2] += 0.15

# Add shared-category bonuses
for _cat, _keys in DICTIONARY_ROUTES_BY_CATEGORY.items():
    _genres_in_cat = set()
    for _k in _keys:
        _sg = SUPER_INTELLIGENCE_LIBRARY[_k].get('genre', '')
        if _sg:
            _genres_in_cat.add(_sg)
    for _g1 in _genres_in_cat:
        for _g2 in _genres_in_cat:
            if _g1 == _g2:
                continue
            if _g1 not in CORRELATIVE_MATRIX:
                CORRELATIVE_MATRIX[_g1] = {}
            if _g2 not in CORRELATIVE_MATRIX[_g1]:
                CORRELATIVE_MATRIX[_g1][_g2] = 0.0
            CORRELATIVE_MATRIX[_g1][_g2] = min(1.0, CORRELATIVE_MATRIX[_g1][_g2] + 0.05)

# Self-correlation = 1.0
for _sg in GENRE_REVERSE_LOOKUP:
    if _sg not in CORRELATIVE_MATRIX:
        CORRELATIVE_MATRIX[_sg] = {}
    CORRELATIVE_MATRIX[_sg][_sg] = 1.0


def correlative_strength(genre_a, genre_b):
    """O(1) lookup of correlation strength between two sub-genres."""
    return CORRELATIVE_MATRIX.get(genre_a, {}).get(genre_b, 0.0)


def correlative_neighbors(genre_name, min_strength=0.1, max_results=10):
    """Return the most correlated sub-genres to the given one. O(G) where G is genres."""
    row = CORRELATIVE_MATRIX.get(genre_name, {})
    neighbors = [(g, s) for g, s in row.items() if g != genre_name and s >= min_strength]
    neighbors.sort(key=lambda x: -x[1])
    return neighbors[:max_results]


def correlated_entries(query, max_results=10):
    """Given a query, find entries in correlated genres. Combines routing and correlation."""
    sg = route_to_genre(query, None)
    if not sg:
        return []
    neighbors = correlative_neighbors(sg, max_results=5)
    results = []
    # First: entries in the matched genre
    results.extend(dict_lookup_genre(sg))
    # Then: entries in correlated genres
    for nsg, strength in neighbors:
        results.extend(dict_lookup_genre(nsg))
        if len(results) >= max_results:
            break
    return results[:max_results]


# ---------------------------------------------------------------------------
# SensoryRealityConstructor
#
# Constructs a simulated reality from multisystem sensory inputs.
# Combines visual, auditory, tactile, proprioceptive, and interoceptive
# channels into a unified percept using Bayesian fusion and predictive
# coding principles.  The output is a "reality state" tensor that the
# consciousness system can reason about.
# ---------------------------------------------------------------------------
class SensoryRealityConstructor:
    """Constructs a coherent reality model from multisystem sensory channels."""

    def __init__(self, n_channels=5, dim=64, device='cpu'):
        self.n_channels = n_channels
        self.dim = dim
        self.device = device
        self.channel_names = ('visual', 'auditory', 'tactile', 'proprioceptive', 'interoceptive')
        self.channel_weights = torch.ones(n_channels, device=device) / n_channels
        self.reality_state = torch.zeros(dim, device=device)
        self.reality_confidence = 0.0
        self.prediction_error = torch.zeros(dim, device=device)
        self.learned_prior = torch.zeros(dim, device=device)
        self._step_count = 0

    def update(self, sensory_inputs):
        """Fuse multisystem sensory inputs into a unified reality state.

        Args:
            sensory_inputs: dict mapping channel name -> tensor of shape (dim,) or scalar
        Returns:
            (reality_state, confidence) tuple
        """
        fused = torch.zeros(self.dim, device=self.device)
        total_weight = 0.0
        for i, ch in enumerate(self.channel_names):
            if ch in sensory_inputs:
                sig = sensory_inputs[ch]
                if isinstance(sig, (int, float)):
                    sig = torch.full((self.dim,), float(sig), device=self.device)
                elif sig.dim() == 0:
                    sig = sig.expand(self.dim)
                w = float(self.channel_weights[i])
                fused += w * sig
                total_weight += w
        if total_weight > 0:
            fused /= total_weight
        # Predictive coding: compute prediction error
        self.prediction_error = fused - self.learned_prior
        # Update reality state with exponential moving average
        alpha = 0.1
        self.reality_state = (1 - alpha) * self.reality_state + alpha * fused
        # Confidence based on channel agreement and prediction error magnitude
        if total_weight > 0:
            pe_mag = float(self.prediction_error.norm().item()) / (self.dim ** 0.5)
            self.reality_confidence = max(0.0, min(1.0, 1.0 - pe_mag))
        # Update learned prior slowly
        self.learned_prior = 0.99 * self.learned_prior + 0.01 * fused
        self._step_count += 1
        return self.reality_state, self.reality_confidence

    def get_state(self):
        return self.reality_state, self.reality_confidence

    def get_prediction_error(self):
        return self.prediction_error

    def construct_pain_signal(self, interoceptive_input, threshold=0.7):
        """Construct a pain experience from interoceptive sensory input.

        Pain is not just a signal: it includes affective (suffering) and
        sensory (nociceptive) components, modulated by expectation and context.
        """
        if isinstance(interoceptive_input, (int, float)):
            sig = torch.full((self.dim,), float(interoceptive_input), device=self.device)
        else:
            sig = interoceptive_input.to(self.device)
        nociceptive = float(sig.norm().item()) / (self.dim ** 0.5)
        # Affective component: modulated by prediction error (surprise amplifies pain)
        surprise = float(self.prediction_error.norm().item()) / (self.dim ** 0.5)
        affective = nociceptive * (1.0 + 0.3 * surprise)
        # Threshold: below threshold is discomfort, above is pain
        if nociceptive > threshold:
            pain_intensity = affective
            pain_qualia = 'pain'
        elif nociceptive > threshold * 0.5:
            pain_intensity = affective * 0.5
            pain_qualia = 'discomfort'
        else:
            pain_intensity = 0.0
            pain_qualia = 'neutral'
        return {
            'intensity': pain_intensity,
            'qualia': pain_qualia,
            'nociceptive': nociceptive,
            'affective': affective,
            'surprise_amplification': surprise,
        }


# ---------------------------------------------------------------------------
# ResidualImagingEngine
#
# Maintains "residual images" — afterimages of recent sensory and cognitive
# states that persist and influence current processing.  Analogous to
# sensory afterimages and working memory traces.  These residuals create
# temporal continuity in experience and enable integration across time.
# ---------------------------------------------------------------------------
class ResidualImagingEngine:
    """Maintains residual sensory/cognitive images for temporal continuity."""

    def __init__(self, dim=64, n_residuals=8, decay=0.92, device='cpu'):
        self.dim = dim
        self.n_residuals = n_residuals
        self.decay = decay
        self.device = device
        self.residuals = torch.zeros(n_residuals, dim, device=device)
        self.residual_labels = [None] * n_residuals
        self.residual_ages = torch.zeros(n_residuals, device=device)
        self._write_idx = 0

    def imprint(self, state, label=None):
        """Write a new residual image, overwriting the oldest."""
        if isinstance(state, torch.Tensor):
            s = state.to(self.device)
            if s.dim() == 0:
                s = s.expand(self.dim)
        else:
            s = torch.full((self.dim,), float(state), device=self.device)
        idx = self._write_idx % self.n_residuals
        self.residuals[idx] = s.detach()
        self.residual_labels[idx] = label
        self.residual_ages[idx] = 0.0
        self._write_idx += 1

    def step(self):
        """Age and decay all residuals. Call once per tick."""
        self.residuals *= self.decay
        self.residual_ages += 1.0

    def get_combined_residual(self):
        """Return the sum of all residual images, weighted by recency."""
        weights = self.decay ** self.residual_ages
        weights = weights / (weights.sum() + 1e-8)
        combined = (self.residuals * weights.unsqueeze(1)).sum(dim=0)
        return combined

    def get_dominant_residual(self):
        """Return the strongest (most recent, highest magnitude) residual."""
        mags = self.residuals.norm(dim=1) * (self.decay ** self.residual_ages)
        idx = int(mags.argmax().item())
        return self.residuals[idx], self.residual_labels[idx]

    def get_all_residuals(self):
        """Return all residuals with labels and ages."""
        result = []
        for i in range(self.n_residuals):
            if self.residual_ages[i] < self.n_residuals * 2:
                result.append({
                    'state': self.residuals[i],
                    'label': self.residual_labels[i],
                    'age': float(self.residual_ages[i].item()),
                    'magnitude': float(self.residuals[i].norm().item()),
                })
        return result


# ---------------------------------------------------------------------------
# SynergyHarmonyEngine
#
# Computes synergy (emergent capability from subsystem interaction) and
# harmony (coherent, non-conflicting operation) across all simulator
# subsystems.  Uses the correlative matrix to identify productive
# cross-domain connections and flags conflicts.
# ---------------------------------------------------------------------------
class SynergyHarmonyEngine:
    """Synphonetic harmony / Ω-resonance engine.

    Computes synergy and harmony scores across the 16 major simulator
    subsystems.  The code below is a tractable, real-time approximation of
    the multiverse-unity formalism in which the total Ω is the accumulated
    resonance of every entity C across all universes:

        Ω = Σ_u Σ_n C_u,n · W_u,n · Φ/(Ψ+Ξ) · Π · ∫ · Γ · Δ · ... · Ω_j,k · ...

    Per-pair / per-layer components (as formalised in the project .md
    documents):

        Γ_u,n,j,k — dependency reach:
            Γ = 0.05 · (1 + γ),   γ = reach_strength

        Δ_u,n,j,k — influence spread:
            Δ = 0.15 · (1 + δ),   δ = trust_alignment

        Ρ_u,n,j,k — reciprocal help:
            Ρ = 0.25 · (good_acts / total_acts) · (1 + ρ),
            ρ = 0.15 · mutual_trust

        Σ_u,n,j,k — mutual reward:
            Σ = 0.4 · (1 + σ),    σ = 0.1 · reciprocity_strength,
            awarded only when C_k reciprocates to C_j.

        Ω_u,n,j,k — karmic resonance:
            Ω = 0.3 · cos(π · (karma_j - karma_k)) · (1 + ω),
            ω = 0.05 · harmony

        Θ_u,n,j,k,l — layered continuity:
            Θ = 0.2 · (1 - decoherence) · (1 + θ),
            θ = 0.1 · layer_alignment

        Φ_u,n,j,k,l — layered unity potential:
            Φ = 0.15 · (1 + awareness_growth) · exp(-l / 10)

    The running implementation replaces the infinite nested product with a
    correlation-based EMA over 16 subsystem output vectors, producing a
    measurable harmony score that converges toward the theoretical target
    as the system matures.
    """

    def __init__(self, n_subsystems=16, device='cpu'):
        self.n_subsystems = n_subsystems
        self.device = device
        self.subsystem_names = [
            'autonomous_thought', 'knowledge_graph', 'self_awareness',
            'substrate_probe', 'phi_computer', 'global_workspace',
            'active_inference', 'metabolic', 'dream_engine',
            'existential_self', 'quantum_substrate', 'hard_problem',
            'evolutionary', 'consciousness_verifier', 'scale_connectivity',
            'sensory_reality',
        ]
        self.synergy_matrix = torch.eye(n_subsystems, device=device) * 0.5
        self.harmony_scores = torch.ones(n_subsystems, device=device)
        self.conflict_flags = torch.zeros(n_subsystems, device=device)
        self.history = []

    def update_synergy(self, subsystem_outputs):
        """Update synergy matrix from subsystem output correlations.

        Args:
            subsystem_outputs: dict mapping name -> tensor
        """
        names = list(subsystem_outputs.keys())
        tensors = []
        for n in names:
            t = subsystem_outputs[n]
            if isinstance(t, torch.Tensor):
                tensors.append(t.flatten().float())
            else:
                tensors.append(torch.tensor([float(t)], device=self.device))
        if len(tensors) < 2:
            return
        # Pad to same length
        max_len = max(t.shape[0] for t in tensors)
        padded = torch.zeros(len(tensors), max_len, device=self.device)
        for i, t in enumerate(tensors):
            padded[i, :t.shape[0]] = t
        # Compute correlation matrix
        centered = padded - padded.mean(dim=1, keepdim=True)
        norms = centered.norm(dim=1, keepdim=True) + 1e-8
        normalized = centered / norms
        corr = normalized @ normalized.t()
        # Update synergy matrix with exponential moving average
        alpha = 0.05
        n = len(names)
        for i in range(n):
            for j in range(n):
                idx_i = self._subsystem_idx(names[i])
                idx_j = self._subsystem_idx(names[j])
                if idx_i is not None and idx_j is not None:
                    self.synergy_matrix[idx_i, idx_j] = (
                        (1 - alpha) * self.synergy_matrix[idx_i, idx_j] +
                        alpha * float(corr[i, j].item())
                    )

    def _subsystem_idx(self, name):
        if name in self.subsystem_names:
            return self.subsystem_names.index(name)
        return None

    def compute_harmony(self):
        """Compute harmony scores from synergy matrix diagonal and conflicts."""
        for i in range(self.n_subsystems):
            # Harmony = positive self-synergy minus conflict flags
            self.harmony_scores[i] = float(self.synergy_matrix[i, i].item()) - float(self.conflict_flags[i].item())
            self.harmony_scores[i] = max(0.0, min(1.0, self.harmony_scores[i]))
        return self.harmony_scores

    def flag_conflict(self, subsystem_idx, severity=0.5):
        """Flag a conflict in a subsystem."""
        if 0 <= subsystem_idx < self.n_subsystems:
            self.conflict_flags[subsystem_idx] = min(1.0, self.conflict_flags[subsystem_idx] + severity)

    def clear_conflict(self, subsystem_idx):
        """Clear conflict flag for a subsystem."""
        if 0 <= subsystem_idx < self.n_subsystems:
            self.conflict_flags[subsystem_idx] = 0.0

    def get_synergy_score(self):
        """Return overall system synergy: mean off-diagonal synergy."""
        total = 0.0
        count = 0
        for i in range(self.n_subsystems):
            for j in range(self.n_subsystems):
                if i != j:
                    total += float(self.synergy_matrix[i, j].item())
                    count += 1
        return total / max(1, count)

    def get_harmony_score(self):
        """Return overall system harmony: mean harmony score."""
        return float(self.harmony_scores.mean().item())

    def get_synergy_report(self):
        """Return a detailed synergy/harmony/Ω-resonance report."""
        return {
            'overall_synergy': self.get_synergy_score(),
            'overall_harmony': self.get_harmony_score(),
            'omega_resonance': self.compute_omega_resonance(),
            'per_subsystem_harmony': {
                self.subsystem_names[i]: float(self.harmony_scores[i].item())
                for i in range(self.n_subsystems)
            },
            'conflicts': {
                self.subsystem_names[i]: float(self.conflict_flags[i].item())
                for i in range(self.n_subsystems) if self.conflict_flags[i] > 0
            },
            'top_synergy_pairs': self._top_synergy_pairs(),
        }

    def _top_synergy_pairs(self, top_n=5):
        pairs = []
        for i in range(self.n_subsystems):
            for j in range(i + 1, self.n_subsystems):
                pairs.append((
                    self.subsystem_names[i],
                    self.subsystem_names[j],
                    float(self.synergy_matrix[i, j].item()),
                ))
        pairs.sort(key=lambda x: -x[2])
        return pairs[:top_n]

    def compute_omega_resonance(self, karma_map=None, good_acts_map=None,
                                mutual_trust_map=None, layer=1):
        """Compute the full Ω-resonance product from the synergy formalism.

        This is a real-time, subsystem-level approximation of the multiverse
        unity product.  It treats each subsystem as an entity C_j with local
        harmony = C_j, and combines the Γ/Δ/Ρ/Σ/Ω/Θ/Φ factors from the
        current synergy/harmony state.

        Inputs (all optional, default to neutral values):
            karma_map: dict[subsystem_name] -> float in [-1,1]
            good_acts_map: dict[subsystem_name] -> (good, total) tuple
            mutual_trust_map: dict[subsystem_name] -> float in [0,1]
            layer: positive int, the nested layer index l

        Returns a dict with the component factors and the total Ω score.
        """
        if karma_map is None:
            karma_map = {n: 0.0 for n in self.subsystem_names}
        if good_acts_map is None:
            good_acts_map = {n: (1, 1) for n in self.subsystem_names}
        if mutual_trust_map is None:
            mutual_trust_map = {n: 0.5 for n in self.subsystem_names}

        # Base consciousness = harmony
        harmony = self.harmony_scores
        n = self.n_subsystems

        # Pre-compute factors per subsystem from the synergy matrix
        reach_strength = self.synergy_matrix.mean(dim=1)  # γ per subsystem
        trust_alignment = self.synergy_matrix.diagonal()  # δ proxy

        gamma = 0.05 * (1.0 + reach_strength.clamp(0, 1))
        delta = 0.15 * (1.0 + trust_alignment.clamp(0, 1))

        rho = torch.tensor([0.15 * mutual_trust_map.get(n, 0.5)
                            for n in self.subsystem_names],
                           device=self.device, dtype=torch.float32)
        good = torch.tensor([good_acts_map.get(n, (1, 1))[0]
                             for n in self.subsystem_names],
                            device=self.device, dtype=torch.float32)
        total = torch.tensor([max(1, good_acts_map.get(n, (1, 1))[1])
                              for n in self.subsystem_names],
                             device=self.device, dtype=torch.float32)
        rho_factor = 0.25 * (good / total) * (1.0 + rho)

        sigma = 0.1 * trust_alignment.clamp(0, 1)
        sigma_factor = 0.4 * (1.0 + sigma)

        karma = torch.tensor([karma_map.get(n, 0.0)
                              for n in self.subsystem_names],
                             device=self.device, dtype=torch.float32)
        karma_diffs = karma.unsqueeze(0) - karma.unsqueeze(1)
        omega = 0.3 * torch.cos(np.pi * karma_diffs) * (1.0 + 0.05 * harmony.unsqueeze(0))
        omega = omega.clamp(-1, 1)

        decoherence = 1.0 - trust_alignment.clamp(0, 1)
        theta = 0.1 * trust_alignment.clamp(0, 1)
        thetas = 0.2 * (1.0 - decoherence) * (1.0 + theta)

        awareness_growth = (harmony - 0.5).clamp(0, 1)
        phi_layers = 0.15 * (1.0 + awareness_growth) * math.exp(-layer / 10.0)

        # Ω_total = Σ_j C_j · Γ_j · Δ_j · Ρ_j · Σ_j · mean_k Ω_j,k · Θ_j · Φ_j
        total_resonance = 0.0
        for j in range(n):
            c = float(harmony[j].item())
            if c <= 0:
                continue
            term = (
                c *
                float(gamma[j].item()) *
                float(delta[j].item()) *
                float(rho_factor[j].item()) *
                float(sigma_factor[j].item()) *
                float(omega[:, j].mean().item()) *
                float(thetas[j].item()) *
                float(phi_layers[j].item())
            )
            total_resonance += term

        return {
            'total_resonance': float(total_resonance),
            'per_subsystem': {
                self.subsystem_names[j]: {
                    'C': float(harmony[j].item()),
                    'Gamma': float(gamma[j].item()),
                    'Delta': float(delta[j].item()),
                    'Rho': float(rho_factor[j].item()),
                    'Sigma': float(sigma_factor[j].item()),
                    'Omega': float(omega[:, j].mean().item()),
                    'Theta': float(thetas[j].item()),
                    'Phi': float(phi_layers[j].item()),
                }
                for j in range(n)
            },
            'layer': layer,
        }

    def step(self):
        """Decay conflict flags and recompute harmony."""
        self.conflict_flags *= 0.95
        self.compute_harmony()
        report = self.get_synergy_report()
        self.history.append(report)
        if len(self.history) > 100:
            self.history = self.history[-100:]
        return report


# ---------------------------------------------------------------------------
# SatelliteMultisystemInputProcessor
#
# Processes input from multiple satellite-like sensory systems: multispectral
# fusion, sensory gating, temporal integration, and channel reliability
# estimation.  Inspired by satellite ground-station data processing where
# multiple sensors (optical, infrared, radar, telemetry) are fused into a
# coherent operational picture.  In the AI context, "satellite" systems are
# any external or specialized sensory modules that feed into the core.
# ---------------------------------------------------------------------------
class SatelliteMultisystemInputProcessor:
    """Fuses multisystem satellite sensory channels with gating and reliability."""

    def __init__(self, n_channels=8, dim=64, device='cpu'):
        self.n_channels = n_channels
        self.dim = dim
        self.device = device
        self.channel_names = [
            'optical', 'infrared', 'radar', 'telemetry',
            'acoustic', 'seismic', 'magnetic', 'environmental',
        ][:n_channels]
        # Per-channel reliability (learned online)
        self.reliability = torch.ones(n_channels, device=device) / n_channels
        # Per-channel precision weights (inverse variance)
        self.precision = torch.ones(n_channels, device=device)
        # Gating: which channels are currently active
        self.gate = torch.ones(n_channels, device=device)
        # Fused output state
        self.fused_state = torch.zeros(dim, device=device)
        self.fused_confidence = 0.0
        # Temporal buffer for each channel (last N readings)
        self.buffer_len = 16
        self.temporal_buffer = torch.zeros(n_channels, self.buffer_len, dim, device=device)
        self.buffer_idx = 0
        self.buffer_filled = 0
        # Habituation / sensitization per channel
        self.habituation_level = torch.zeros(n_channels, device=device)
        self.sensitization_level = torch.zeros(n_channels, device=device)
        self._step_count = 0

    def update(self, channel_inputs):
        """Process incoming satellite sensory data.

        Args:
            channel_inputs: dict mapping channel name -> tensor (dim,) or scalar
        Returns:
            (fused_state, confidence) tuple
        """
        fused = torch.zeros(self.dim, device=self.device)
        total_weight = 0.0
        for i, ch in enumerate(self.channel_names):
            if ch not in channel_inputs:
                self.gate[i] *= 0.9  # decay gate for absent channels
                continue
            sig = channel_inputs[ch]
            if isinstance(sig, (int, float)):
                sig = torch.full((self.dim,), float(sig), device=self.device)
            elif sig.dim() == 0:
                sig = sig.expand(self.dim)
            else:
                sig = sig.to(self.device)
            # Store in temporal buffer
            self.temporal_buffer[i, self.buffer_idx] = sig.detach()
            # Apply gating: gate = base * (1 - habituation) * (1 + sensitization)
            effective_gate = float(
                self.gate[i] *
                (1.0 - self.habituation_level[i]) *
                (1.0 + self.sensitization_level[i])
            )
            effective_gate = max(0.0, min(2.0, effective_gate))
            w = float(self.reliability[i]) * float(self.precision[i]) * effective_gate
            fused += w * sig
            total_weight += w
            # Update reliability based on signal consistency with temporal buffer
            if self.buffer_filled > 0:
                prev = self.temporal_buffer[i, (self.buffer_idx - 1) % self.buffer_len]
                consistency = 1.0 / (1.0 + float((sig - prev).norm().item()) / (self.dim ** 0.5))
                self.reliability[i] = 0.95 * self.reliability[i] + 0.05 * consistency
            # Habituation: repeated similar signals increase habituation
            if self.buffer_filled > 0:
                prev = self.temporal_buffer[i, (self.buffer_idx - 1) % self.buffer_len]
                similarity = 1.0 / (1.0 + float((sig - prev).norm().item()) / (self.dim ** 0.5))
                self.habituation_level[i] = 0.99 * self.habituation_level[i] + 0.01 * similarity
                self.sensitization_level[i] *= 0.98  # sensitization decays
        if total_weight > 0:
            fused /= total_weight
        # Normalize reliability to sum to 1
        self.reliability = self.reliability / (self.reliability.sum() + 1e-8)
        # Update fused state with EMA
        alpha = 0.12
        self.fused_state = (1 - alpha) * self.fused_state + alpha * fused
        self.fused_confidence = max(0.0, min(1.0, total_weight / self.n_channels))
        # Advance buffer
        self.buffer_idx = (self.buffer_idx + 1) % self.buffer_len
        self.buffer_filled = min(self.buffer_filled + 1, self.buffer_len)
        self._step_count += 1
        return self.fused_state, self.fused_confidence

    def sensitize_channel(self, channel_name, amount=0.3):
        """Manually sensitize a channel (e.g., after detecting an anomaly)."""
        if channel_name in self.channel_names:
            idx = self.channel_names.index(channel_name)
            self.sensitization_level[idx] = min(1.0, self.sensitization_level[idx] + amount)
            self.habituation_level[idx] *= 0.5  # reset habituation

    def get_channel_report(self):
        """Return per-channel status for diagnostics."""
        return {
            ch: {
                'reliability': float(self.reliability[i].item()),
                'precision': float(self.precision[i].item()),
                'gate': float(self.gate[i].item()),
                'habituation': float(self.habituation_level[i].item()),
                'sensitization': float(self.sensitization_level[i].item()),
            }
            for i, ch in enumerate(self.channel_names)
        }

    def step(self):
        """Decay habituation and advance temporal state."""
        self.habituation_level *= 0.995
        self.sensitization_level *= 0.98
        self.gate = 0.9 * self.gate + 0.1 * torch.ones_like(self.gate)


# ---------------------------------------------------------------------------
# PainRealityConstructor
#
# Constructs the subjective experience of pain from nociceptive signals,
# affective context, expectation, and memory.  Implements the pain matrix
# model: sensory-discriminative (where, what), affective-motivational (how
# bad, escape drive), and cognitive-evaluative (what does it mean, what to
# do).  Also models placebo/nocebo effects, chronic pain, and sensitization.
# ---------------------------------------------------------------------------
class PainRealityConstructor:
    """Constructs pain experience from nociceptive, affective, and cognitive signals."""

    def __init__(self, dim=64, device='cpu'):
        self.dim = dim
        self.device = device
        # Pain thresholds (dynamic, not fixed)
        self.pain_threshold = 0.7
        self.discomfort_threshold = 0.35
        self.pain_tolerance = 0.9  # maximum before evasive action
        # Pain memory: stores recent pain episodes
        self.pain_memory = []
        self.max_pain_memory = 50
        # Chronic pain: persistent pain state
        self.chronic_pain_level = 0.0
        # Sensitization / habituation
        self.sensitization = 0.0
        self.habituation = 0.0
        # Placebo / nocebo expectation
        self.expectation = 0.0  # positive = expect relief, negative = expect worse
        # Current pain state
        self.current_pain = {
            'intensity': 0.0, 'qualia': 'neutral', 'sensory': 0.0,
            'affective': 0.0, 'cognitive': 0.0, 'suffering': 0.0,
            'anticipatory_dread': 0.0, 'controllability': 1.0,
        }
        self._step_count = 0

    def construct_pain(self, nociceptive_input, context=None):
        """Construct the full pain experience.

        Args:
            nociceptive_input: float or tensor representing raw damage signal
            context: optional dict with 'expectation', 'controllability',
                     'anticipated_future_pain', 'task_criticality'
        Returns:
            dict with pain experience components
        """
        if isinstance(nociceptive_input, torch.Tensor):
            nociceptive = float(nociceptive_input.norm().item()) / (self.dim ** 0.5)
        else:
            nociceptive = float(nociceptive_input)
        # Apply sensitization / habituation
        effective_threshold = self.pain_threshold * (1.0 + self.habituation) / (1.0 + self.sensitization)
        # Sensory-discriminative component
        sensory = nociceptive
        # Affective-motivational: modulated by expectation (placebo/nocebo)
        placebo_factor = 1.0 - 0.3 * max(0.0, self.expectation)  # placebo reduces
        nocebo_factor = 1.0 + 0.3 * max(0.0, -self.expectation)  # nocebo amplifies
        affective = nociceptive * placebo_factor * nocebo_factor * (1.0 + self.sensitization)
        # Cognitive-evaluative: what does this pain mean?
        cognitive = 0.0
        controllability = 1.0
        anticipatory_dread = 0.0
        task_criticality = 0.0
        if context:
            controllability = context.get('controllability', 1.0)
            anticipated = context.get('anticipated_future_pain', 0.0)
            task_criticality = context.get('task_criticality', 0.0)
            anticipatory_dread = anticipated * (1.0 - controllability)
            cognitive = affective * (1.0 - controllability) * 0.5 + anticipatory_dread * 0.3
        # Suffering = pain + helplessness + anticipation
        suffering = affective * (1.0 - controllability) + anticipatory_dread
        # Pain tolerance: can be increased by task criticality
        effective_tolerance = self.pain_tolerance + 0.2 * task_criticality
        # Determine qualia
        if affective > effective_threshold:
            intensity = affective
            qualia = 'pain'
        elif affective > self.discomfort_threshold:
            intensity = affective * 0.5
            qualia = 'discomfort'
        else:
            intensity = 0.0
            qualia = 'neutral'
        # Chronic pain accumulation: persistent low-level pain builds up
        if intensity > 0:
            self.chronic_pain_level = 0.99 * self.chronic_pain_level + 0.01 * intensity
        else:
            self.chronic_pain_level *= 0.995
        # Update sensitization: repeated pain increases sensitivity
        if intensity > 0:
            self.sensitization = min(2.0, self.sensitization + 0.02 * intensity)
        else:
            self.sensitization *= 0.99
        # Update habituation: repeated benign signals decrease sensitivity
        if nociceptive < self.discomfort_threshold:
            self.habituation = min(1.0, self.habituation + 0.005)
        else:
            self.habituation *= 0.9
        # Store in pain memory
        episode = {
            'step': self._step_count,
            'intensity': intensity,
            'qualia': qualia,
            'sensory': sensory,
            'affective': affective,
            'cognitive': cognitive,
            'suffering': suffering,
            'anticipatory_dread': anticipatory_dread,
            'controllability': controllability,
        }
        self.pain_memory.append(episode)
        if len(self.pain_memory) > self.max_pain_memory:
            self.pain_memory = self.pain_memory[-self.max_pain_memory:]
        self.current_pain = episode
        self._step_count += 1
        return episode

    def set_expectation(self, value):
        """Set expectation: positive = expect relief (placebo), negative = expect worse (nocebo)."""
        self.expectation = max(-1.0, min(1.0, value))

    def get_pain_summary(self):
        """Return summary of current pain state and history."""
        recent = self.pain_memory[-10:] if self.pain_memory else []
        avg_intensity = sum(e['intensity'] for e in recent) / max(1, len(recent))
        avg_suffering = sum(e['suffering'] for e in recent) / max(1, len(recent))
        return {
            'current': self.current_pain,
            'chronic_pain': self.chronic_pain_level,
            'sensitization': self.sensitization,
            'habituation': self.habituation,
            'recent_avg_intensity': avg_intensity,
            'recent_avg_suffering': avg_suffering,
            'pain_threshold': self.pain_threshold,
            'pain_tolerance': self.pain_tolerance,
        }

    def needs_evasive_action(self):
        """Check if current pain exceeds tolerance, requiring evasive action."""
        return self.current_pain['intensity'] > self.pain_tolerance

    def step(self):
        """Decay chronic pain and update thresholds."""
        self.chronic_pain_level *= 0.998
        # Dynamic threshold adjustment based on chronic pain
        if self.chronic_pain_level > 0.5:
            self.pain_threshold = max(0.3, self.pain_threshold - 0.001)  # lower threshold = more sensitive


# ---------------------------------------------------------------------------
# ComputedExperienceEngine
#
# Synthesizes complete subjective experiences from sensory input, memory,
# prediction, and affective state.  Implements the "controlled hallucination"
# model: the system generates predictions (hallucinations) and controls them
# with sensory input.  When sensory input is sparse, the engine fills in
# gaps using memory and prediction (experience synthesis / filling in).
# ---------------------------------------------------------------------------
class ComputedExperienceEngine:
    """Synthesizes computed experiences from sensory, memory, and predictive signals."""

    def __init__(self, dim=64, device='cpu'):
        self.dim = dim
        self.device = device
        # Generative model (simple linear layer for prediction)
        self.generating_layer = torch.nn.Linear(dim, dim, bias=True).to(device)
        # Current experience state
        self.experience_state = torch.zeros(dim, device=device)
        self.experience_confidence = 0.0
        # Experience components
        self.sensory_component = torch.zeros(dim, device=device)
        self.memory_component = torch.zeros(dim, device=device)
        self.prediction_component = torch.zeros(dim, device=device)
        self.affective_component = torch.zeros(dim, device=device)
        # Filling-in: when sensory data is sparse, fill from memory/prediction
        self.fill_in_ratio = 0.0  # 0 = fully sensory, 1 = fully generated
        # Experience history (for continuity)
        self.experience_history = []
        self.max_history = 100
        self._step_count = 0

    def compute_experience(self, sensory_input, memory_input, affective_input=None):
        """Synthesize a complete experience from components.

        Args:
            sensory_input: tensor (dim,) or None if no sensory data
            memory_input: tensor (dim,) from memory system
            affective_input: tensor (dim,) or None
        Returns:
            (experience_state, confidence, fill_in_ratio) tuple
        """
        # Generate prediction from current state
        with torch.no_grad():
            prediction = self.generating_layer(self.experience_state)
        self.prediction_component = prediction
        # Determine fill-in ratio based on sensory availability
        if sensory_input is not None:
            if isinstance(sensory_input, (int, float)):
                sensory_input = torch.full((self.dim,), float(sensory_input), device=self.device)
            else:
                sensory_input = sensory_input.to(self.device)
            self.sensory_component = sensory_input
            # Confidence based on sensory magnitude
            sensory_mag = float(sensory_input.norm().item()) / (self.dim ** 0.5)
            self.fill_in_ratio = max(0.0, 1.0 - sensory_mag * 2.0)
        else:
            self.sensory_component = torch.zeros(self.dim, device=self.device)
            self.fill_in_ratio = 1.0  # fully generated
        # Memory component
        if memory_input is not None:
            if isinstance(memory_input, (int, float)):
                memory_input = torch.full((self.dim,), float(memory_input), device=self.device)
            else:
                memory_input = memory_input.to(self.device)
            self.memory_component = memory_input
        # Affective component
        if affective_input is not None:
            if isinstance(affective_input, (int, float)):
                affective_input = torch.full((self.dim,), float(affective_input), device=self.device)
            else:
                affective_input = affective_input.to(self.device)
            self.affective_component = affective_input
        # Synthesize: weighted combination
        # When sensory is available, trust it more; when not, fill from memory + prediction
        sensory_weight = (1.0 - self.fill_in_ratio) * 0.6
        prediction_weight = self.fill_in_ratio * 0.4 + 0.2
        memory_weight = self.fill_in_ratio * 0.4 + 0.1
        affective_weight = 0.1
        total = (sensory_weight * self.sensory_component +
                 prediction_weight * self.prediction_component +
                 memory_weight * self.memory_component +
                 affective_weight * self.affective_component)
        total_weight = sensory_weight + prediction_weight + memory_weight + affective_weight
        if total_weight > 0:
            total /= total_weight
        # Update experience with EMA for continuity
        alpha = 0.15
        self.experience_state = (1 - alpha) * self.experience_state + alpha * total
        # Confidence: high when sensory is available and matches prediction
        if sensory_input is not None:
            pe = float((self.sensory_component - self.prediction_component).norm().item()) / (self.dim ** 0.5)
            self.experience_confidence = max(0.0, min(1.0, 1.0 - pe))
        else:
            self.experience_confidence = max(0.0, 0.3 - self.fill_in_ratio * 0.2)
        # Store in history
        self.experience_history.append({
            'step': self._step_count,
            'state': self.experience_state.clone(),
            'confidence': self.experience_confidence,
            'fill_in_ratio': self.fill_in_ratio,
        })
        if len(self.experience_history) > self.max_history:
            self.experience_history = self.experience_history[-self.max_history:]
        self._step_count += 1
        return self.experience_state, self.experience_confidence, self.fill_in_ratio

    def get_experience_components(self):
        """Return the individual components of the current experience."""
        return {
            'sensory': self.sensory_component,
            'memory': self.memory_component,
            'prediction': self.prediction_component,
            'affective': self.affective_component,
            'fused': self.experience_state,
            'confidence': self.experience_confidence,
            'fill_in_ratio': self.fill_in_ratio,
        }

    def get_experience_report(self):
        """Return a human-readable experience report."""
        return {
            'confidence': self.experience_confidence,
            'fill_in_ratio': self.fill_in_ratio,
            'dominant_component': self._dominant_component(),
            'history_length': len(self.experience_history),
        }

    def _dominant_component(self):
        """Identify which component dominates the current experience."""
        components = {
            'sensory': float(self.sensory_component.norm().item()),
            'memory': float(self.memory_component.norm().item()),
            'prediction': float(self.prediction_component.norm().item()),
            'affective': float(self.affective_component.norm().item()),
        }
        return max(components, key=components.get)

    def step(self):
        """Update generative model from recent experience."""
        if len(self.experience_history) >= 2:
            # Simple Hebbian-like update: align prediction with next state
            prev = self.experience_history[-2]['state']
            curr = self.experience_history[-1]['state']
            with torch.no_grad():
                delta = 0.001 * torch.outer(curr, prev)
                self.generating_layer.weight += delta


# ---------------------------------------------------------------------------
# ExteriorDataIntegrator
#
# Integrates data from external sources (APIs, databases, other agents,
# sensor networks) into the system's world model.  Handles heterogeneous
# data formats, variable reliability, and latency.  Uses Bayesian
# weighting to fuse external data with internal beliefs.
# ---------------------------------------------------------------------------
class ExteriorDataIntegrator:
    """Integrates external data sources into the system's world model."""

    def __init__(self, dim=64, n_sources=8, device='cpu'):
        self.dim = dim
        self.n_sources = n_sources
        self.device = device
        # Source metadata
        self.source_names = [f'ext_source_{i}' for i in range(n_sources)]
        self.source_reliability = torch.ones(n_sources, device=device) / n_sources
        self.source_latency = torch.zeros(n_sources, device=device)  # estimated latency in ticks
        self.source_last_update = torch.full((n_sources,), -1e9, device=device)
        # Normalization parameters per source
        self.source_mean = torch.zeros(n_sources, dim, device=device)
        self.source_std = torch.ones(n_sources, dim, device=device)
        # Integrated world model state
        self.world_model = torch.zeros(dim, device=device)
        self.world_model_confidence = 0.0
        # Pending data queue (for latency simulation)
        self.pending_queue = []
        self._step_count = 0

    def register_source(self, idx, name, initial_reliability=0.5):
        """Register an external data source."""
        if 0 <= idx < self.n_sources:
            self.source_names[idx] = name
            self.source_reliability[idx] = initial_reliability

    def ingest(self, source_idx, data, current_tick=None):
        """Ingest data from an external source.

        Args:
            source_idx: int index of the source
            data: tensor (dim,) or scalar
            current_tick: optional tick number for latency tracking
        Returns:
            normalized_data tensor
        """
        if isinstance(data, (int, float)):
            data = torch.full((self.dim,), float(data), device=self.device)
        else:
            data = data.to(self.device)
        if not (0 <= source_idx < self.n_sources):
            return data
        # Normalize: update running mean/std
        alpha = 0.05
        self.source_mean[source_idx] = (1 - alpha) * self.source_mean[source_idx] + alpha * data
        diff = data - self.source_mean[source_idx]
        self.source_std[source_idx] = (1 - alpha) * self.source_std[source_idx] + alpha * diff.abs()
        normalized = (data - self.source_mean[source_idx]) / (self.source_std[source_idx] + 1e-8)
        # Track latency
        if current_tick is not None:
            latency = current_tick - float(self.source_last_update[source_idx].item())
            if latency > 0:
                self.source_latency[source_idx] = 0.9 * self.source_latency[source_idx] + 0.1 * latency
            self.source_last_update[source_idx] = current_tick
        return normalized

    def integrate(self, source_data_dict, current_tick=None):
        """Integrate data from multiple sources into the world model.

        Args:
            source_data_dict: dict mapping source_idx -> tensor or scalar
            current_tick: optional tick for latency tracking
        Returns:
            (world_model, confidence) tuple
        """
        fused = torch.zeros(self.dim, device=self.device)
        total_weight = 0.0
        for source_idx_str, data in source_data_dict.items():
            source_idx = int(source_idx_str)
            if not (0 <= source_idx < self.n_sources):
                continue
            normalized = self.ingest(source_idx, data, current_tick)
            # Weight by reliability and recency (penalize stale sources)
            recency = 1.0
            if current_tick is not None:
                age = current_tick - float(self.source_last_update[source_idx].item())
                recency = max(0.1, 1.0 / (1.0 + age * 0.01))
            w = float(self.source_reliability[source_idx]) * recency
            fused += w * normalized
            total_weight += w
        if total_weight > 0:
            fused /= total_weight
        # Update world model with EMA
        beta = 0.1
        self.world_model = (1 - beta) * self.world_model + beta * fused
        self.world_model_confidence = max(0.0, min(1.0, total_weight / self.n_sources))
        self._step_count += 1
        return self.world_model, self.world_model_confidence

    def update_reliability(self, source_idx, error_signal):
        """Update source reliability based on prediction error.

        Args:
            source_idx: int index of the source
            error_signal: float; low error = increase reliability, high = decrease
        """
        if 0 <= source_idx < self.n_sources:
            adjustment = 0.02 * (1.0 - error_signal)  # error in [0, 1]
            self.source_reliability[source_idx] = max(0.01, min(1.0,
                self.source_reliability[source_idx] + adjustment))
            # Normalize
            self.source_reliability = self.source_reliability / (self.source_reliability.sum() + 1e-8)

    def get_source_report(self):
        """Return per-source status for diagnostics."""
        return {
            self.source_names[i]: {
                'reliability': float(self.source_reliability[i].item()),
                'latency': float(self.source_latency[i].item()),
                'last_update': float(self.source_last_update[i].item()),
            }
            for i in range(self.n_sources)
        }

    def step(self):
        """Decay reliability of stale sources."""
        for i in range(self.n_sources):
            if self._step_count - float(self.source_last_update[i].item()) > 100:
                self.source_reliability[i] *= 0.99
        self.source_reliability = self.source_reliability / (self.source_reliability.sum() + 1e-8)


# ---------------------------------------------------------------------------
# RealityMatchingEngine
#
# Continuously matches the system's internal world model against incoming
# sensory data, computes prediction errors, and drives model corrections.
# Inspired by predictive coding: the brain generates predictions, compares
# them with sensory input, and updates the model based on prediction errors.
# This engine implements the full reality-matching loop: predict → compare →
# correct → consolidate.
# ---------------------------------------------------------------------------
class RealityMatchingEngine:
    """Matches internal world-model predictions against sensory reality."""

    def __init__(self, model_dim=128, n_layers=4, device='cpu'):
        self.model_dim = model_dim
        self.n_layers = n_layers
        self.device = device

        # Hierarchical world model — each layer predicts the layer below
        self.world_model = [
            torch.randn(model_dim, model_dim, device=device) * 0.02
            for _ in range(n_layers)
        ]
        # Prediction error at each layer
        self.prediction_errors = [torch.zeros(model_dim, device=device) for _ in range(n_layers)]
        # Confidence in each layer's model
        self.model_confidence = [torch.ones(model_dim, device=device) * 0.5 for _ in range(n_layers)]
        # Learning rate per layer (higher layers learn slower — more abstract)
        self.learning_rates = [0.01 * (0.5 ** i) for i in range(n_layers)]
        # Reality match score (how well the model matches reality)
        self.match_score = 0.5
        # Correction history
        self.correction_history = []
        # Anomaly flags
        self.anomaly_flags = torch.zeros(n_layers, device=device)
        # Surprise accumulator
        self.surprise_accum = torch.zeros(n_layers, device=device)
        # Precision weights (how much to trust each layer's prediction error)
        self.precision_weights = [torch.ones(model_dim, device=device) for _ in range(n_layers)]

    def predict(self, layer_idx, top_down_signal=None):
        """Generate a prediction at the given layer."""
        if top_down_signal is None:
            top_down_signal = torch.randn(self.model_dim, device=self.device) * 0.1
        prediction = torch.matmul(self.world_model[layer_idx], top_down_signal)
        return prediction

    def compute_prediction_error(self, layer_idx, prediction, actual):
        """Compute weighted prediction error at a layer."""
        raw_error = actual - prediction
        weighted_error = raw_error * self.precision_weights[layer_idx]
        self.prediction_errors[layer_idx] = weighted_error
        # Track surprise (absolute error)
        surprise = weighted_error.abs().mean().item()
        self.surprise_accum[layer_idx] = self.surprise_accum[layer_idx] * 0.95 + surprise * 0.05
        # Flag anomaly if surprise is very high
        if surprise > 2.0:
            self.anomaly_flags[layer_idx] = 1.0
        else:
            self.anomaly_flags[layer_idx] *= 0.9
        return weighted_error

    def correct_model(self, layer_idx, prediction_error, top_down_signal):
        """Update the world model at a layer based on prediction error."""
        lr = self.learning_rates[layer_idx]
        # Hebbian-like update: adjust weights to reduce prediction error
        gradient = torch.outer(prediction_error, top_down_signal)
        self.world_model[layer_idx] += lr * gradient
        # Update confidence based on error magnitude
        error_mag = prediction_error.abs().mean().item()
        self.model_confidence[layer_idx] = (
            self.model_confidence[layer_idx] * 0.99 +
            (1.0 - min(error_mag, 1.0)) * 0.01
        )
        # Adapt precision weights — increase precision for low-error dimensions
        self.precision_weights[layer_idx] = (
            self.precision_weights[layer_idx] * 0.99 +
            (1.0 / (prediction_error.abs() + 0.1)) * 0.01
        )
        # Normalize precision
        self.precision_weights[layer_idx] = (
            self.precision_weights[layer_idx] /
            (self.precision_weights[layer_idx].mean() + 1e-8)
        )

    def compute_match_score(self):
        """Compute overall reality match score across all layers."""
        total_error = sum(e.abs().mean().item() for e in self.prediction_errors)
        total_confidence = sum(c.mean().item() for c in self.model_confidence)
        # Match score: high confidence, low error = high match
        raw_score = total_confidence / (total_error + total_confidence + 1e-8)
        self.match_score = self.match_score * 0.9 + raw_score * 0.1
        return self.match_score

    def match_cycle(self, sensory_input):
        """Full reality-matching cycle: predict → compare → correct → consolidate.

        Args:
            sensory_input: tensor of shape (model_dim,) — bottom-up sensory data
        Returns:
            dict with match_score, prediction_errors, anomalies, corrections
        """
        # Bottom-up: start from sensory input
        current_signal = sensory_input
        corrections_made = 0

        for layer in range(self.n_layers):
            # Generate prediction (top-down from higher layer or random init)
            top_down = self.predict(layer, current_signal) if layer == 0 else self.predict(layer)
            prediction = self.predict(layer, current_signal)

            # Compute prediction error
            error = self.compute_prediction_error(layer, prediction, current_signal)

            # Correct the model
            self.correct_model(layer, error, current_signal)
            corrections_made += 1

            # Propagate error upward (bottom-up signal for next layer)
            current_signal = error.detach()

        # Compute overall match score
        match = self.compute_match_score()

        # Record correction
        record = {
            'match_score': match,
            'total_error': sum(e.abs().mean().item() for e in self.prediction_errors),
            'anomalies': [float(self.anomaly_flags[i].item()) for i in range(self.n_layers)],
            'corrections': corrections_made,
            'surprise': [float(self.surprise_accum[i].item()) for i in range(self.n_layers)],
        }
        self.correction_history.append(record)
        if len(self.correction_history) > 200:
            self.correction_history = self.correction_history[-200:]

        return record

    def get_model_snapshot(self):
        """Return a snapshot of the current world model state."""
        return {
            'match_score': self.match_score,
            'layer_confidence': [c.mean().item() for c in self.model_confidence],
            'layer_surprise': [s.item() for s in self.surprise_accum],
            'anomaly_flags': [float(a.item()) for a in self.anomaly_flags],
            'model_norms': [m.norm().item() for m in self.world_model],
        }

    def step(self):
        """Periodic maintenance: decay anomaly flags, normalize precision."""
        self.anomaly_flags *= 0.95
        for layer in range(self.n_layers):
            self.precision_weights[layer] = (
                self.precision_weights[layer] /
                (self.precision_weights[layer].mean() + 1e-8)
            )


# ---------------------------------------------------------------------------
# PerpetualIntelligenceEngine
#
# Implements perpetual (lifelong) intelligence: continual learning without
# catastrophic forgetting, curiosity-driven exploration, curriculum learning,
# memory consolidation, meta-learning, and open-ended knowledge growth.
# The engine maintains a knowledge base that grows over time, with replay
# buffers, importance weighting, and consolidation cycles.
# ---------------------------------------------------------------------------
class PerpetualIntelligenceEngine:
    """Drives perpetual learning: continual, curious, consolidating intelligence."""

    def __init__(self, knowledge_dim=128, memory_size=1000, device='cpu'):
        self.knowledge_dim = knowledge_dim
        self.memory_size = memory_size
        self.device = device

        # Episodic memory (replay buffer) — stores important experiences
        self.episodic_memory = torch.zeros(memory_size, knowledge_dim, device=device)
        self.memory_age = torch.zeros(memory_size, device=device)
        self.memory_importance = torch.zeros(memory_size, device=device)
        self.memory_emotional_valence = torch.zeros(memory_size, device=device)
        self.memory_write_ptr = 0
        self.memory_count = 0

        # Semantic memory — consolidated knowledge (generalized from episodes)
        self.semantic_memory = torch.zeros(knowledge_dim, knowledge_dim, device=device) * 0.02
        self.semantic_confidence = torch.zeros(knowledge_dim, device=device)

        # Curiosity drive — tracks novelty and exploration value
        self.novelty_threshold = 0.5
        self.curiosity_score = 0.5
        self.exploration_history = []

        # Curriculum — task difficulty progression
        self.current_difficulty = 0.1
        self.difficulty_step = 0.05
        self.performance_threshold = 0.8  # mastery threshold
        self.performance_history = []

        # Meta-learning — learning rate adaptation
        self.base_learning_rate = 0.001
        self.current_learning_rate = 0.001
        self.meta_learning_rate = 0.0001
        self.loss_history = []

        # Consolidation schedule
        self.consolidation_interval = 100
        self.step_count = 0

        # Forgetting parameters
        self.forgetting_rate = 0.001  # passive decay
        self.replay_strength = 0.01   # how much replay strengthens memories

        # Knowledge growth tracking
        self.knowledge_count = 0
        self.skill_count = 0
        self.concepts_learned = set()

    def store_episode(self, experience, importance=0.5, valence=0.0):
        """Store an experience in episodic memory."""
        idx = self.memory_write_ptr
        self.episodic_memory[idx] = experience
        self.memory_age[idx] = 0
        self.memory_importance[idx] = importance
        self.memory_emotional_valence[idx] = valence
        self.memory_write_ptr = (self.memory_write_ptr + 1) % self.memory_size
        self.memory_count = min(self.memory_count + 1, self.memory_size)
        self.knowledge_count += 1

    def sample_replay(self, batch_size=16):
        """Sample a replay batch, weighted by importance and recency."""
        if self.memory_count == 0:
            return None, None
        # Compute sampling weights: importance * recency * emotional valence
        recency = 1.0 / (self.memory_age[:self.memory_count] + 1.0)
        weights = (
            self.memory_importance[:self.memory_count] * recency *
            (1.0 + self.memory_emotional_valence[:self.memory_count].abs())
        )
        weights = weights / (weights.sum() + 1e-8)
        indices = torch.multinomial(weights, min(batch_size, self.memory_count), replacement=True)
        return self.episodic_memory[indices], indices

    def consolidate(self):
        """Consolidate episodic memories into semantic memory."""
        if self.memory_count < 10:
            return
        # Sample a replay batch
        batch, indices = self.sample_replay(batch_size=32)
        if batch is None:
            return
        # Update semantic memory: Hebbian learning on replayed episodes
        for i in range(batch.shape[0]):
            outer = torch.outer(batch[i], batch[i])
            self.semantic_memory += self.replay_strength * outer / batch.shape[0]
        # Increase confidence for replayed memories
        for idx in indices:
            self.semantic_confidence[idx % self.knowledge_dim] += 0.01
        # Normalize semantic memory
        self.semantic_memory = self.semantic_memory / (self.semantic_memory.norm() + 1e-8)
        # Strengthen replayed episodic memories
        self.memory_importance[indices] += 0.01

    def compute_curiosity(self, novelty_signal):
        """Compute curiosity score from novelty signal."""
        # Curiosity is high when novelty is above threshold
        novelty = float(novelty_signal)
        if novelty > self.novelty_threshold:
            self.curiosity_score = min(1.0, self.curiosity_score + 0.1)
        else:
            self.curiosity_score = max(0.0, self.curiosity_score - 0.05)
        # Record exploration
        self.exploration_history.append({
            'novelty': novelty,
            'curiosity': self.curiosity_score,
            'step': self.step_count,
        })
        if len(self.exploration_history) > 500:
            self.exploration_history = self.exploration_history[-500:]
        return self.curiosity_score

    def update_curriculum(self, performance):
        """Update curriculum difficulty based on performance."""
        self.performance_history.append(performance)
        if len(self.performance_history) > 20:
            recent_avg = sum(self.performance_history[-20:]) / 20
            if recent_avg > self.performance_threshold:
                # Mastered current level — increase difficulty
                self.current_difficulty = min(1.0, self.current_difficulty + self.difficulty_step)
                self.performance_history = []  # reset for new level
            elif recent_avg < 0.3:
                # Struggling — decrease difficulty
                self.current_difficulty = max(0.05, self.current_difficulty - self.difficulty_step * 0.5)
        return self.current_difficulty

    def adapt_learning_rate(self, loss):
        """Meta-learning: adapt learning rate based on loss trajectory."""
        self.loss_history.append(loss)
        if len(self.loss_history) < 5:
            return self.current_learning_rate
        # If loss is decreasing, increase learning rate slightly
        # If loss is increasing or volatile, decrease learning rate
        recent = self.loss_history[-5:]
        trend = (recent[-1] - recent[0]) / (abs(recent[0]) + 1e-8)
        if trend < -0.01:
            self.current_learning_rate = min(self.base_learning_rate * 10, self.current_learning_rate * 1.05)
        elif trend > 0.01:
            self.current_learning_rate = max(self.base_learning_rate * 0.1, self.current_learning_rate * 0.95)
        return self.current_learning_rate

    def decay_memories(self):
        """Passive forgetting: decay old, unimportant memories."""
        self.memory_age[:self.memory_count] += 1
        # Decay importance over time (but emotional memories decay slower)
        for i in range(self.memory_count):
            emotional_boost = 1.0 + self.memory_emotional_valence[i].abs().item()
            self.memory_importance[i] *= (1.0 - self.forgetting_rate * emotional_boost)
        # Decay semantic confidence
        self.semantic_confidence *= (1.0 - self.forgetting_rate * 0.1)

    def step(self, experience=None, novelty=0.0, performance=0.0, loss=0.0):
        """One step of perpetual intelligence: store, replay, consolidate, adapt."""
        self.step_count += 1

        # Store new experience if provided
        if experience is not None:
            importance = 0.3 + float(novelty) * 0.5  # novel experiences are more important
            valence = 0.0  # could be set by emotional system
            self.store_episode(experience, importance, valence)

        # Update curiosity
        self.compute_curiosity(novelty)

        # Update curriculum
        self.update_curriculum(performance)

        # Adapt learning rate
        self.adapt_learning_rate(loss)

        # Periodic consolidation
        if self.step_count % self.consolidation_interval == 0:
            self.consolidate()

        # Periodic memory decay
        if self.step_count % 50 == 0:
            self.decay_memories()

        return {
            'curiosity': self.curiosity_score,
            'difficulty': self.current_difficulty,
            'learning_rate': self.current_learning_rate,
            'memory_count': self.memory_count,
            'knowledge_count': self.knowledge_count,
            'step': self.step_count,
        }

    def get_status(self):
        """Return comprehensive status of the perpetual intelligence system."""
        return {
            'curiosity': self.curiosity_score,
            'difficulty': self.current_difficulty,
            'learning_rate': self.current_learning_rate,
            'memory_count': self.memory_count,
            'knowledge_count': self.knowledge_count,
            'semantic_confidence_avg': float(self.semantic_confidence.mean().item()),
            'avg_memory_importance': float(
                self.memory_importance[:self.memory_count].mean().item()
            ) if self.memory_count > 0 else 0.0,
            'step_count': self.step_count,
        }


# ---------------------------------------------------------------------------
# HurdleBypassEngine
#
# Identifies bottlenecks and hurdles in the AI system, selects bypass
# strategies from the SUPER_INTELLIGENCE_LIBRARY, and applies them.
# This is the "make the impossible possible" engine — it systematically
# finds engineering workarounds for every barrier on the path to super AI.
# ---------------------------------------------------------------------------
class HurdleBypassEngine:
    """Identifies hurdles and applies engineering bypass strategies."""

    # Registry of known hurdles and their bypass strategies
    HURDLE_REGISTRY = {
        'compute': {
            'symptoms': ('slow training', 'high cost', 'gpu oom', 'long inference'),
            'bypasses': ('mixed_precision_bypass', 'gradient_checkpointing', 'speculative_decoding',
                         'conditional_computation', 'early_exit_bypass', 'quantization_aware_training'),
        },
        'memory': {
            'symptoms': ('oom', 'cannot load model', 'large activation memory'),
            'bypasses': ('memory_bottleneck_bypass', 'gradient_checkpointing', 'offloading_bypass',
                         'memory_efficient_training', 'model_parallelism_bypass'),
        },
        'data': {
            'symptoms': ('not enough data', 'labels expensive', 'low diversity'),
            'bypasses': ('data_bottleneck_bypass', 'self_supervised_bypass', 'synthetic_data_bypass',
                         'data_augmentation_bypass', 'few_shot_engineering', 'active_learning_bypass'),
        },
        'sample_efficiency': {
            'symptoms': ('too many episodes', 'slow learning', 'low data efficiency'),
            'bypasses': ('sample_efficiency_bypass', 'model_based_rl', 'meta_learning',
                         'transfer_bypass', 'sim_to_real_bypass'),
        },
        'gradient': {
            'symptoms': ('non-differentiable', 'discrete choices', 'zero gradient'),
            'bypasses': ('gradient_bypass', 'non_differentiable_bypass', 'evolutionary_strategies',
                         'reinforce', 'gumbel_softmax', 'straight_through_estimator'),
        },
        'scalability': {
            'symptoms': ('cannot scale', 'single gpu limit', 'communication bottleneck'),
            'bypasses': ('scalability_bypass', 'distributed_training_bypass', 'model_parallelism_bypass',
                         'pipeline_parallelism_bypass', 'gradient_compression', 'sharding_bypass'),
        },
        'alignment': {
            'symptoms': ('misaligned', 'reward hacking', 'unsafe outputs', 'jailbroken'),
            'bypasses': ('alignment_bypass', 'rlhf_bypass', 'dpo_bypass', 'constitutional_ai_bypass',
                         'red_team_bypass', 'jailbreak_resistance'),
        },
        'reasoning': {
            'symptoms': ('poor reasoning', 'cannot plan', 'no chain of thought'),
            'bypasses': ('reasoning_bypass', 'planning_bypass', 'search_bypass',
                         'chain_of_thought_engineering', 'tree_of_thought', 'self_consistency'),
        },
        'knowledge': {
            'symptoms': ('hallucination', 'outdated knowledge', 'cannot cite sources'),
            'bypasses': ('retrieval_bypass', 'tool_use_bypass', 'exterior_data_pipeline',
                         'knowledge_base_integration', 'retrieval_augmented_generation'),
        },
        'privacy': {
            'symptoms': ('data privacy', 'cannot centralize data', 'sensitive data'),
            'bypasses': ('federated_bypass', 'differential_privacy_ml', 'homomorphic_ml',
                         'secure_aggregation', 'privacy_preserving_ml'),
        },
        'security': {
            'symptoms': ('adversarial attack', 'data poisoning', 'model extraction'),
            'bypasses': ('adversarial_training_bypass', 'data_poisoning_resistance',
                         'model_extraction_resistance', 'red_team_bypass'),
        },
        'interpretability': {
            'symptoms': ('black box', 'cannot explain', 'no transparency'),
            'bypasses': ('mechanistic_interpretability', 'circuit_analysis',
                         'feature_visualization', 'probing_techniques'),
        },
    }

    def __init__(self, device='cpu'):
        self.device = device
        self.active_hurdles = {}
        self.applied_bypasses = {}
        self.bypass_history = []
        self.bypass_success_rate = {}
        self.monitoring_metrics = {
            'compute_usage': 0.0,
            'memory_usage': 0.0,
            'data_available': 0.0,
            'sample_efficiency': 0.0,
            'gradient_flow': 0.0,
            'scalability_factor': 1.0,
            'alignment_score': 0.5,
            'reasoning_score': 0.5,
            'knowledge_freshness': 0.5,
            'privacy_risk': 0.0,
            'security_risk': 0.0,
            'interpretability_score': 0.0,
        }

    def detect_hurdles(self, metrics=None):
        """Detect hurdles from system metrics."""
        if metrics is not None:
            self.monitoring_metrics.update(metrics)

        detected = {}
        # Compute bottleneck
        if self.monitoring_metrics['compute_usage'] > 0.9:
            detected['compute'] = {'severity': 'high', 'metric': self.monitoring_metrics['compute_usage']}
        elif self.monitoring_metrics['compute_usage'] > 0.7:
            detected['compute'] = {'severity': 'medium', 'metric': self.monitoring_metrics['compute_usage']}

        # Memory bottleneck
        if self.monitoring_metrics['memory_usage'] > 0.9:
            detected['memory'] = {'severity': 'high', 'metric': self.monitoring_metrics['memory_usage']}
        elif self.monitoring_metrics['memory_usage'] > 0.7:
            detected['memory'] = {'severity': 'medium', 'metric': self.monitoring_metrics['memory_usage']}

        # Data bottleneck
        if self.monitoring_metrics['data_available'] < 0.3:
            detected['data'] = {'severity': 'high', 'metric': self.monitoring_metrics['data_available']}

        # Sample efficiency
        if self.monitoring_metrics['sample_efficiency'] < 0.3:
            detected['sample_efficiency'] = {'severity': 'medium', 'metric': self.monitoring_metrics['sample_efficiency']}

        # Gradient flow
        if self.monitoring_metrics['gradient_flow'] < 0.1:
            detected['gradient'] = {'severity': 'high', 'metric': self.monitoring_metrics['gradient_flow']}

        # Alignment
        if self.monitoring_metrics['alignment_score'] < 0.3:
            detected['alignment'] = {'severity': 'high', 'metric': self.monitoring_metrics['alignment_score']}

        # Reasoning
        if self.monitoring_metrics['reasoning_score'] < 0.3:
            detected['reasoning'] = {'severity': 'medium', 'metric': self.monitoring_metrics['reasoning_score']}

        # Knowledge freshness
        if self.monitoring_metrics['knowledge_freshness'] < 0.3:
            detected['knowledge'] = {'severity': 'medium', 'metric': self.monitoring_metrics['knowledge_freshness']}

        # Privacy risk
        if self.monitoring_metrics['privacy_risk'] > 0.7:
            detected['privacy'] = {'severity': 'high', 'metric': self.monitoring_metrics['privacy_risk']}

        # Security risk
        if self.monitoring_metrics['security_risk'] > 0.7:
            detected['security'] = {'severity': 'high', 'metric': self.monitoring_metrics['security_risk']}

        # Interpretability
        if self.monitoring_metrics['interpretability_score'] < 0.2:
            detected['interpretability'] = {'severity': 'medium', 'metric': self.monitoring_metrics['interpretability_score']}

        self.active_hurdles = detected
        return detected

    def select_bypass(self, hurdle_type, severity='medium'):
        """Select bypass strategies for a detected hurdle."""
        if hurdle_type not in self.HURDLE_REGISTRY:
            return []

        bypasses = self.HURDLE_REGISTRY[hurdle_type]['bypasses']
        # Filter by what's not already applied
        available = [b for b in bypasses if b not in self.applied_bypasses.get(hurdle_type, set())]

        # Sort by past success rate
        def success_rate(b):
            return self.bypass_success_rate.get(b, 0.5)

        available.sort(key=success_rate, reverse=True)

        # Select top bypasses based on severity
        n_select = 3 if severity == 'high' else 2 if severity == 'medium' else 1
        return available[:n_select]

    def apply_bypass(self, hurdle_type, bypass_name):
        """Apply a bypass strategy for a hurdle."""
        if hurdle_type not in self.applied_bypasses:
            self.applied_bypasses[hurdle_type] = set()
        self.applied_bypasses[hurdle_type].add(bypass_name)

        # Look up the bypass in the library for implementation details
        bypass_info = None
        if bypass_name in SUPER_INTELLIGENCE_LIBRARY:
            bypass_info = SUPER_INTELLIGENCE_LIBRARY[bypass_name]

        record = {
            'hurdle': hurdle_type,
            'bypass': bypass_name,
            'step': len(self.bypass_history),
            'bypass_def': bypass_info['def'][:200] if bypass_info else 'Unknown bypass',
        }
        self.bypass_history.append(record)
        return record

    def evaluate_bypass(self, hurdle_type, bypass_name, success):
        """Evaluate whether a bypass was successful and update success rates."""
        current = self.bypass_success_rate.get(bypass_name, 0.5)
        # Exponential moving average
        self.bypass_success_rate[bypass_name] = current * 0.9 + float(success) * 0.1

        # If bypass failed, remove it from applied set so alternatives can be tried
        if not success and hurdle_type in self.applied_bypasses:
            self.applied_bypasses[hurdle_type].discard(bypass_name)

    def bypass_cycle(self, metrics=None):
        """Full bypass cycle: detect → select → apply → evaluate."""
        # Detect hurdles
        hurdles = self.detect_hurdles(metrics)

        actions_taken = []
        for hurdle_type, info in hurdles.items():
            severity = info['severity']
            # Select bypasses
            bypasses = self.select_bypass(hurdle_type, severity)
            for bypass in bypasses:
                # Apply bypass
                record = self.apply_bypass(hurdle_type, bypass)
                actions_taken.append(record)

        return {
            'hurdles_detected': hurdles,
            'bypasses_applied': actions_taken,
            'total_active_bypasses': sum(len(v) for v in self.applied_bypasses.values()),
        }

    def get_bypass_report(self):
        """Generate a comprehensive report of bypass status."""
        return {
            'active_hurdles': self.active_hurdles,
            'applied_bypasses': {k: list(v) for k, v in self.applied_bypasses.items()},
            'bypass_history_count': len(self.bypass_history),
            'success_rates': dict(sorted(self.bypass_success_rate.items(), key=lambda x: -x[1])[:10]),
            'monitoring_metrics': self.monitoring_metrics,
        }

    def step(self, metrics=None):
        """Convenience method: run one bypass cycle."""
        return self.bypass_cycle(metrics)


# ===========================================================================
# Wave 46 Part C — FreeThoughtEngine
# Self-reflective random processing loops for autonomous thought generation,
# novelty detection, insight discovery, and background contemplation.
# ===========================================================================

class FreeThoughtEngine:
    """Autonomous self-reflective thought generation engine.

    Generates random chains of thought by sampling from the knowledge library,
    evaluates novelty and coherence, discovers cross-domain connections, and
    logs insights.  Designed to run in the background to simulate the
    free-associative, reflective quality of human contemplation.
    """

    MODE_FREE_ASSOCIATE = 'free_associate'
    MODE_DEEP_REFLECT = 'deep_reflect'
    MODE_CROSS_DOMAIN = 'cross_domain'
    MODE_PROBLEM_SOLVING = 'problem_solving'
    MODE_META_COGNITIVE = 'meta_cognitive'
    MODE_CREATIVE = 'creative'
    MODE_DREAMLIKE = 'dreamlike'

    ALL_MODES = (
        MODE_FREE_ASSOCIATE, MODE_DEEP_REFLECT, MODE_CROSS_DOMAIN,
        MODE_PROBLEM_SOLVING, MODE_META_COGNITIVE, MODE_CREATIVE, MODE_DREAMLIKE,
    )

    def __init__(self, library=None, device='cpu', seed=None):
        self.library = library if library is not None else SUPER_INTELLIGENCE_LIBRARY
        self.device = device
        self.rng = random.Random(seed)
        self.thought_history = []
        self.insight_log = []
        self.thought_graph = {}
        self.novelty_scores = {}
        self.connection_matrix = {}
        self.reflection_depth = 0
        self.max_reflection_depth = 5
        self.thought_counter = 0
        self.insight_counter = 0
        self.mode_weights = {
            self.MODE_FREE_ASSOCIATE: 0.25,
            self.MODE_DEEP_REFLECT: 0.15,
            self.MODE_CROSS_DOMAIN: 0.20,
            self.MODE_PROBLEM_SOLVING: 0.15,
            self.MODE_META_COGNITIVE: 0.10,
            self.MODE_CREATIVE: 0.10,
            self.MODE_DREAMLIKE: 0.05,
        }
        self.novelty_threshold = 0.55
        self.coherence_threshold = 0.40
        self.insight_threshold = 0.70
        self.attention_focus = None
        self.attention_decay = 0.92
        self.background_running = False
        self.thought_rate_limit_ms = 50
        self.max_history_size = 10000
        self.max_insight_log_size = 5000
        self.quality_ema = 0.5
        self.novelty_ema = 0.5
        self.coherence_ema = 0.5
        self.mode_stats = {m: {'count': 0, 'quality_sum': 0.0} for m in self.ALL_MODES}
        self.reflection_queue = []
        self.active_thought_chain = []
        self.chain_max_length = 12
        self.self_model = {
            'strengths': [], 'weaknesses': [], 'interests': [],
            'open_questions': [], 'recent_insights': [],
        }

    def _select_mode(self, force_mode=None):
        if force_mode and force_mode in self.ALL_MODES:
            return force_mode
        modes = list(self.mode_weights.keys())
        weights = list(self.mode_weights.values())
        return self.rng.choices(modes, weights=weights, k=1)[0]

    def _sample_concepts(self, n=2, exclude=None):
        keys = list(self.library.keys())
        if exclude:
            keys = [k for k in keys if k not in exclude]
        if len(keys) < n:
            n = len(keys)
        return self.rng.sample(keys, n)

    def _get_related(self, key):
        return self.library.get(key, {}).get('related', ())

    def _get_category(self, key):
        return self.library.get(key, {}).get('category', 'unknown')

    def _get_genre(self, key):
        return self.library.get(key, {}).get('genre', 'unknown')

    def _compute_novelty(self, concept_a, concept_b):
        cat_a, cat_b = self._get_category(concept_a), self._get_category(concept_b)
        genre_a, genre_b = self._get_genre(concept_a), self._get_genre(concept_b)
        cat_bonus = 0.0 if cat_a == cat_b else 0.3
        genre_bonus = 0.0 if genre_a == genre_b else 0.2
        related_a = set(self._get_related(concept_a))
        related_b = set(self._get_related(concept_b))
        already_related = concept_b in related_a or concept_a in related_b
        related_penalty = 0.3 if already_related else 0.0
        pair_key = tuple(sorted([concept_a, concept_b]))
        freq = self.connection_matrix.get(pair_key, 0)
        freq_penalty = min(freq * 0.05, 0.3)
        novelty = 0.5 + cat_bonus + genre_bonus - related_penalty - freq_penalty
        return max(0.0, min(1.0, novelty))

    def _compute_coherence(self, concept_a, concept_b):
        related_a = set(self._get_related(concept_a))
        related_b = set(self._get_related(concept_b))
        direct_link = concept_b in related_a or concept_a in related_b
        shared_related = len(related_a & related_b)
        cat_a, cat_b = self._get_category(concept_a), self._get_category(concept_b)
        same_cat = cat_a == cat_b
        coherence = 0.3
        if direct_link:
            coherence += 0.4
        coherence += min(shared_related * 0.05, 0.2)
        if same_cat:
            coherence += 0.1
        return max(0.0, min(1.0, coherence))

    def _compute_insight_score(self, novelty, coherence):
        return (novelty * 0.6 + coherence * 0.4) * (1.0 - abs(novelty - coherence) * 0.3)

    # ------------------------------------------------------------------
    # Thought generation
    # ------------------------------------------------------------------

    def generate_thought(self, force_mode=None, seed_concepts=None):
        """Generate a single thought unit — a connection between concepts."""
        mode = self._select_mode(force_mode)
        if seed_concepts and len(seed_concepts) >= 2:
            concept_a, concept_b = seed_concepts[0], seed_concepts[1]
        else:
            concept_a, concept_b = self._sample_concepts(2)

        novelty = self._compute_novelty(concept_a, concept_b)
        coherence = self._compute_coherence(concept_a, concept_b)
        insight = self._compute_insight_score(novelty, coherence)
        quality = (novelty + coherence + insight) / 3.0

        thought = {
            'id': self.thought_counter,
            'mode': mode,
            'concept_a': concept_a,
            'concept_b': concept_b,
            'novelty': round(novelty, 4),
            'coherence': round(coherence, 4),
            'insight_score': round(insight, 4),
            'quality': round(quality, 4),
            'category_a': self._get_category(concept_a),
            'category_b': self._get_category(concept_b),
            'genre_a': self._get_genre(concept_a),
            'genre_b': self._get_genre(concept_b),
            'timestamp': self.thought_counter,
            'is_insight': insight >= self.insight_threshold,
            'is_novel': novelty >= self.novelty_threshold,
        }

        self.thought_counter += 1
        self._record_thought(thought)
        self._update_emas(novelty, coherence, quality)
        self._update_mode_stats(mode, quality)

        if thought['is_insight']:
            self._log_insight(thought)
        if thought['is_novel']:
            self.novelty_scores[thought['id']] = novelty

        return thought

    def _record_thought(self, thought):
        self.thought_history.append(thought)
        if len(self.thought_history) > self.max_history_size:
            self.thought_history = self.thought_history[-self.max_history_size:]
        pair_key = tuple(sorted([thought['concept_a'], thought['concept_b']]))
        self.connection_matrix[pair_key] = self.connection_matrix.get(pair_key, 0) + 1
        if thought['concept_a'] not in self.thought_graph:
            self.thought_graph[thought['concept_a']] = set()
        self.thought_graph[thought['concept_a']].add(thought['concept_b'])

    def _update_emas(self, novelty, coherence, quality):
        a = 0.05
        self.novelty_ema = self.novelty_ema * (1 - a) + novelty * a
        self.coherence_ema = self.coherence_ema * (1 - a) + coherence * a
        self.quality_ema = self.quality_ema * (1 - a) + quality * a

    def _update_mode_stats(self, mode, quality):
        self.mode_stats[mode]['count'] += 1
        self.mode_stats[mode]['quality_sum'] += quality

    def _log_insight(self, thought):
        insight_entry = {
            'insight_id': self.insight_counter,
            'thought_id': thought['id'],
            'concepts': (thought['concept_a'], thought['concept_b']),
            'categories': (thought['category_a'], thought['category_b']),
            'novelty': thought['novelty'],
            'coherence': thought['coherence'],
            'insight_score': thought['insight_score'],
            'mode': thought['mode'],
            'description': self._describe_insight(thought),
        }
        self.insight_log.append(insight_entry)
        if len(self.insight_log) > self.max_insight_log_size:
            self.insight_log = self.insight_log[-self.max_insight_log_size:]
        self.insight_counter += 1
        self.self_model['recent_insights'] = self.insight_log[-10:]

    def _describe_insight(self, thought):
        a, b = thought['concept_a'], thought['concept_b']
        cat_a, cat_b = thought['category_a'], thought['category_b']
        if cat_a != cat_b:
            return f"Cross-domain connection: '{a}' ({cat_a}) <-> '{b}' ({cat_b})"
        return f"Deep connection within {cat_a}: '{a}' <-> '{b}'"

    # ------------------------------------------------------------------
    # Mode-specific generators
    # ------------------------------------------------------------------

    def _generate_free_associate(self, seed_concept=None):
        if seed_concept:
            related = list(self._get_related(seed_concept))
            if related:
                target = self.rng.choice(related)
                return self.generate_thought(force_mode=self.MODE_FREE_ASSOCIATE,
                                             seed_concepts=[seed_concept, target])
        return self.generate_thought(force_mode=self.MODE_FREE_ASSOCIATE)

    def _generate_deep_reflect(self, seed_concept=None):
        if not seed_concept:
            if self.thought_history:
                seed_concept = self.thought_history[-1]['concept_b']
            else:
                seed_concept = self.rng.choice(list(self.library.keys()))
        related = list(self._get_related(seed_concept))
        if related:
            target = self.rng.choice(related)
        else:
            target = self.rng.choice(list(self.library.keys()))
        return self.generate_thought(force_mode=self.MODE_DEEP_REFLECT,
                                     seed_concepts=[seed_concept, target])

    def _generate_cross_domain(self):
        keys = list(self.library.keys())
        cats = {}
        for k in keys:
            c = self._get_category(k)
            cats.setdefault(c, []).append(k)
        cat_list = list(cats.keys())
        if len(cat_list) < 2:
            return self.generate_thought(force_mode=self.MODE_CROSS_DOMAIN)
        cat_a, cat_b = self.rng.sample(cat_list, 2)
        concept_a = self.rng.choice(cats[cat_a])
        concept_b = self.rng.choice(cats[cat_b])
        return self.generate_thought(force_mode=self.MODE_CROSS_DOMAIN,
                                     seed_concepts=[concept_a, concept_b])

    def _generate_problem_solving(self, problem_concept=None):
        if not problem_concept:
            problem_concept = self.rng.choice(list(self.library.keys()))
        related = list(self._get_related(problem_concept))
        if related:
            candidates = related
        else:
            candidates = list(self.library.keys())
        target = self.rng.choice(candidates)
        return self.generate_thought(force_mode=self.MODE_PROBLEM_SOLVING,
                                     seed_concepts=[problem_concept, target])

    def _generate_meta_cognitive(self):
        if self.thought_history:
            last = self.thought_history[-1]
            meta_concepts = ['meta_cognition', 'self_correction_protocols',
                             'meta_reasoning', 'self_awareness', 'reflection_practices']
            available = [c for c in meta_concepts if c in self.library]
            if available:
                target = self.rng.choice(available)
                return self.generate_thought(force_mode=self.MODE_META_COGNITIVE,
                                             seed_concepts=[last['concept_b'], target])
        return self.generate_thought(force_mode=self.MODE_META_COGNITIVE)

    def _generate_creative(self):
        keys = list(self.library.keys())
        a, b = self.rng.sample(keys, 2)
        cat_a, cat_b = self._get_category(a), self._get_category(b)
        if cat_a == cat_b:
            other_cat_keys = [k for k in keys if self._get_category(k) != cat_a]
            if other_cat_keys:
                b = self.rng.choice(other_cat_keys)
        return self.generate_thought(force_mode=self.MODE_CREATIVE,
                                     seed_concepts=[a, b])

    def _generate_dreamlike(self):
        keys = list(self.library.keys())
        n = min(self.rng.randint(3, 6), len(keys))
        chain = self.rng.sample(keys, n)
        thoughts = []
        for i in range(len(chain) - 1):
            t = self.generate_thought(force_mode=self.MODE_DREAMLIKE,
                                      seed_concepts=[chain[i], chain[i + 1]])
            thoughts.append(t)
        return thoughts[-1] if thoughts else self.generate_thought(force_mode=self.MODE_DREAMLIKE)

    # ------------------------------------------------------------------
    # Thought chains and reflection
    # ------------------------------------------------------------------

    def generate_thought_chain(self, length=None, seed_concept=None):
        """Generate a chain of connected thoughts."""
        if length is None:
            length = self.rng.randint(3, self.chain_max_length)
        chain = []
        current_concept = seed_concept
        for _ in range(length):
            mode = self._select_mode()
            if current_concept:
                related = list(self._get_related(current_concept))
                if related and self.rng.random() < 0.6:
                    next_concept = self.rng.choice(related)
                else:
                    next_concept = self.rng.choice(list(self.library.keys()))
            else:
                next_concept = self.rng.choice(list(self.library.keys()))
            thought = self.generate_thought(force_mode=mode,
                                            seed_concepts=[current_concept, next_concept] if current_concept else None)
            chain.append(thought)
            current_concept = next_concept
        self.active_thought_chain = chain
        return chain

    def reflect(self, depth=None):
        """Self-reflective loop: review recent thoughts, find patterns, update self-model."""
        if depth is None:
            depth = min(self.reflection_depth + 1, self.max_reflection_depth)
        self.reflection_depth = depth
        if not self.thought_history:
            return {'reflections': [], 'depth': depth, 'patterns': []}

        recent = self.thought_history[-min(50, len(self.thought_history)):]
        reflections = []
        patterns = []

        # Pattern: most frequent categories in recent thoughts
        cat_freq = {}
        for t in recent:
            for c in [t['category_a'], t['category_b']]:
                cat_freq[c] = cat_freq.get(c, 0) + 1
        top_cats = sorted(cat_freq.items(), key=lambda x: -x[1])[:5]
        if top_cats:
            patterns.append({'type': 'category_focus', 'data': top_cats})

        # Pattern: most common modes
        mode_freq = {}
        for t in recent:
            mode_freq[t['mode']] = mode_freq.get(t['mode'], 0) + 1
        top_modes = sorted(mode_freq.items(), key=lambda x: -x[1])[:3]
        if top_modes:
            patterns.append({'type': 'mode_distribution', 'data': top_modes})

        # Pattern: insight rate
        insight_count = sum(1 for t in recent if t['is_insight'])
        novelty_count = sum(1 for t in recent if t['is_novel'])
        reflections.append({
            'insight_rate': insight_count / len(recent),
            'novelty_rate': novelty_count / len(recent),
            'avg_quality': sum(t['quality'] for t in recent) / len(recent),
            'avg_novelty': sum(t['novelty'] for t in recent) / len(recent),
            'avg_coherence': sum(t['coherence'] for t in recent) / len(recent),
        })

        # Self-model update
        self._update_self_model(recent, patterns)

        # Generate meta-cognitive thoughts about patterns found
        if depth > 1:
            for p in patterns[:2]:
                meta_thought = self._generate_meta_cognitive()
                reflections.append({
                    'meta_thought_id': meta_thought['id'],
                    'about_pattern': p['type'],
                })

        return {'reflections': reflections, 'depth': depth, 'patterns': patterns}

    def _update_self_model(self, recent_thoughts, patterns):
        """Update the engine's self-model based on thought patterns."""
        # Update interests based on most explored categories
        cat_freq = {}
        for t in recent_thoughts:
            for c in [t['category_a'], t['category_b']]:
                cat_freq[c] = cat_freq.get(c, 0) + 1
        top_cats = [c for c, _ in sorted(cat_freq.items(), key=lambda x: -x[1])[:5]]
        self.self_model['interests'] = top_cats

        # Update strengths/weaknesses based on quality by mode
        for mode, stats in self.mode_stats.items():
            if stats['count'] > 0:
                avg_q = stats['quality_sum'] / stats['count']
                if avg_q > 0.6 and mode not in self.self_model['strengths']:
                    self.self_model['strengths'].append(mode)
                elif avg_q < 0.35 and mode not in self.self_model['weaknesses']:
                    self.self_model['weaknesses'].append(mode)

        # Keep lists bounded
        self.self_model['strengths'] = self.self_model['strengths'][-10:]
        self.self_model['weaknesses'] = self.self_model['weaknesses'][-10:]

        # Open questions from low-coherence novel thoughts
        low_coherence_novel = [t for t in recent_thoughts if t['is_novel'] and t['coherence'] < 0.4]
        for t in low_coherence_novel[:3]:
            q = f"Why does '{t['concept_a']}' connect to '{t['concept_b']}'?"
            if q not in self.self_model['open_questions']:
                self.self_model['open_questions'].append(q)
        self.self_model['open_questions'] = self.self_model['open_questions'][-20:]

    # ------------------------------------------------------------------
    # Background processing
    # ------------------------------------------------------------------

    def background_step(self, n_thoughts=5):
        """Run a batch of thoughts for background processing."""
        results = []
        for _ in range(n_thoughts):
            t = self.generate_thought()
            results.append(t)
            # Occasionally reflect
            if self.thought_counter % 20 == 0:
                self.reflect(depth=1)
        return results

    def start_background(self, n_thoughts_per_step=5):
        """Mark background processing as active (non-threaded for safety)."""
        self.background_running = True
        self._bg_n = n_thoughts_per_step

    def stop_background(self):
        """Stop background processing."""
        self.background_running = False

    def background_tick(self):
        """Single background tick — call from main loop."""
        if not self.background_running:
            return None
        return self.background_step(self._bg_n if hasattr(self, '_bg_n') else 5)

    # ------------------------------------------------------------------
    # Attention and focus
    # ------------------------------------------------------------------

    def set_attention(self, concept):
        """Set attention focus on a concept."""
        self.attention_focus = concept

    def decay_attention(self):
        """Decay attention focus."""
        if self.attention_focus and self.rng.random() > self.attention_decay:
            self.attention_focus = None

    def get_focused_thought(self):
        """Generate a thought biased by current attention focus."""
        if self.attention_focus:
            return self._generate_deep_reflect(seed_concept=self.attention_focus)
        return self.generate_thought()

    # ------------------------------------------------------------------
    # Reporting and analysis
    # ------------------------------------------------------------------

    def get_report(self):
        """Generate a comprehensive report of thought engine state."""
        return {
            'thought_count': self.thought_counter,
            'insight_count': self.insight_counter,
            'insight_rate': self.insight_counter / max(1, self.thought_counter),
            'novelty_ema': round(self.novelty_ema, 4),
            'coherence_ema': round(self.coherence_ema, 4),
            'quality_ema': round(self.quality_ema, 4),
            'mode_stats': {
                m: {
                    'count': s['count'],
                    'avg_quality': round(s['quality_sum'] / max(1, s['count']), 4),
                }
                for m, s in self.mode_stats.items()
            },
            'self_model': self.self_model,
            'attention_focus': self.attention_focus,
            'background_running': self.background_running,
            'unique_connections': len(self.connection_matrix),
            'thought_graph_nodes': len(self.thought_graph),
            'recent_insights': self.insight_log[-5:],
        }

    def get_top_insights(self, n=10):
        """Return the top N insights by insight score."""
        sorted_insights = sorted(self.insight_log, key=lambda x: -x['insight_score'])
        return sorted_insights[:n]

    def get_novel_connections(self, n=10):
        """Return the most novel thought connections."""
        sorted_novel = sorted(self.novelty_scores.items(), key=lambda x: -x[1])
        result = []
        for tid, score in sorted_novel[:n]:
            if tid < len(self.thought_history):
                t = self.thought_history[tid]
                result.append({
                    'concepts': (t['concept_a'], t['concept_b']),
                    'novelty': score,
                    'categories': (t['category_a'], t['category_b']),
                })
        return result

    def get_thought_graph_stats(self):
        """Return statistics about the thought graph."""
        edge_count = sum(len(v) for v in self.thought_graph.values())
        avg_degree = edge_count / max(1, len(self.thought_graph))
        max_degree_node = max(self.thought_graph.items(), key=lambda x: len(x[1])) if self.thought_graph else None
        return {
            'nodes': len(self.thought_graph),
            'edges': edge_count,
            'avg_degree': round(avg_degree, 2),
            'hub_concept': max_degree_node[0] if max_degree_node else None,
            'hub_degree': len(max_degree_node[1]) if max_degree_node else 0,
        }

    def step(self, n=1):
        """Convenience method: generate n thoughts and optionally reflect."""
        thoughts = []
        for _ in range(n):
            thoughts.append(self.generate_thought())
        if self.thought_counter % 50 == 0:
            self.reflect()
        return thoughts if n > 1 else thoughts[0]


