# ===========================================================================
# WAVE 46 PART A: HARD-CODED MATH EQUATIONS & FORMULAS FOR INTELLIGENCE
#
# A comprehensive dictionary of mathematical equations that the AI can use
# to compute, reason, and figure things out. These are not just definitions
# — they are operational formulas with parameters, units, and usage notes.
# The AI can look up any formula by name and apply it to solve problems.
# ===========================================================================

MATH_FORMULAS = {}

# --- Information Theory ---
MATH_FORMULAS['shannon_entropy'] = {
    'formula': 'H(X) = -sum(p(x) * log2(p(x)) for x in X)',
    'description': 'Shannon entropy — measures uncertainty/information content of a random variable.',
    'parameters': {'p': 'probability distribution over outcomes X'},
    'units': 'bits',
    'range': '[0, log2(|X|)]',
    'usage': 'Measure how much information is in a signal, how unpredictable a distribution is.',
    'python': 'lambda p: -sum(pi * math.log2(pi) for pi in p if pi > 0)',
    'category': 'information_theory',
    'importance': 5,
}
MATH_FORMULAS['cross_entropy'] = {
    'formula': 'H(P, Q) = -sum(p(x) * log(q(x)) for x in X)',
    'description': 'Cross-entropy between distributions P and Q — measures how well Q approximates P.',
    'parameters': {'p': 'true distribution', 'q': 'predicted distribution'},
    'units': 'bits',
    'usage': 'Loss function for classification — minimize to make predictions match truth.',
    'python': 'lambda p, q: -sum(pi * math.log(max(qi, 1e-12)) for pi, qi in zip(p, q))',
    'category': 'information_theory',
    'importance': 5,
}
MATH_FORMULAS['kl_divergence'] = {
    'formula': 'KL(P||Q) = sum(p(x) * log(p(x)/q(x)) for x in X)',
    'description': 'Kullback-Leibler divergence — measures how much P differs from Q (asymmetric).',
    'parameters': {'p': 'first distribution', 'q': 'second distribution'},
    'units': 'bits',
    'range': '[0, infinity)',
    'usage': 'Measure distribution shift, regularization in VAEs, reward model training.',
    'python': 'lambda p, q: sum(pi * math.log(max(pi, 1e-12) / max(qi, 1e-12)) for pi, qi in zip(p, q) if pi > 0)',
    'category': 'information_theory',
    'importance': 5,
}
MATH_FORMULAS['mutual_information'] = {
    'formula': 'I(X;Y) = H(X) - H(X|Y) = sum(p(x,y) * log(p(x,y)/(p(x)*p(y))) for x,y)',
    'description': 'Mutual information — how much knowing Y reduces uncertainty about X.',
    'parameters': {'X': 'random variable 1', 'Y': 'random variable 2'},
    'units': 'bits',
    'range': '[0, min(H(X), H(Y))]',
    'usage': 'Feature selection, measuring dependence between variables, information bottleneck.',
    'category': 'information_theory',
    'importance': 4,
}
MATH_FORMULAS['fisher_information'] = {
    'formula': 'I(theta) = E[(d/dtheta log L(theta;X))^2]',
    'description': 'Fisher information — measures how much data tells us about a parameter.',
    'parameters': {'theta': 'parameter', 'L': 'likelihood function', 'X': 'data'},
    'usage': 'Cramér-Rao bound, natural gradient descent, variational inference.',
    'category': 'information_theory',
    'importance': 4,
}
MATH_FORMULAS['channel_capacity'] = {
    'formula': 'C = max_{p(x)} I(X;Y)',
    'description': 'Channel capacity — maximum rate at which information can be reliably transmitted.',
    'parameters': {'X': 'input', 'Y': 'output', 'p(x)': 'input distribution'},
    'units': 'bits per channel use',
    'usage': 'Communication limits, attention capacity, workspace bandwidth.',
    'category': 'information_theory',
    'importance': 3,
}

