# --- Learning & Optimization ---
MATH_FORMULAS['gradient_descent'] = {
    'formula': 'theta_{t+1} = theta_t - lr * gradient(L, theta_t)',
    'description': 'Gradient descent — update parameters in the direction of decreasing loss.',
    'parameters': {'theta': 'parameters', 'lr': 'learning rate', 'L': 'loss function'},
    'usage': 'Core optimization algorithm for neural networks.',
    'category': 'optimization',
    'importance': 5,
}
MATH_FORMULAS['adam_optimizer'] = {
    'formula': 'm_t = b1*m_{t-1} + (1-b1)*g_t; v_t = b2*v_{t-1} + (1-b2)*g_t^2; theta_t = theta_{t-1} - lr * m_hat / (sqrt(v_hat) + eps)',
    'description': 'Adam optimizer — adaptive moment estimation with bias correction.',
    'parameters': {'m': 'first moment', 'v': 'second moment', 'b1': '0.9', 'b2': '0.999', 'eps': '1e-8'},
    'usage': 'Most common optimizer for deep learning.',
    'category': 'optimization',
    'importance': 5,
}
MATH_FORMULAS['newton_method'] = {
    'formula': 'x_{n+1} = x_n - f(x_n) / f\'(x_n)',
    'description': 'Newton\'s method — find roots using function value and derivative.',
    'parameters': {'f': 'function', "f'": 'derivative', 'x_0': 'initial guess'},
    'usage': 'Fast convergence for root finding, optimization (with Hessian).',
    'category': 'optimization',
    'importance': 4,
}
MATH_FORMULAS['bayes_theorem'] = {
    'formula': 'P(H|D) = P(D|H) * P(H) / P(D)',
    'description': 'Bayes\' theorem — update beliefs given evidence.',
    'parameters': {'H': 'hypothesis', 'D': 'data/evidence', 'P(H)': 'prior', 'P(D|H)': 'likelihood'},
    'usage': 'Belief updating, inference, prediction under uncertainty.',
    'category': 'probability',
    'importance': 5,
}
MATH_FORMULAS['bayesian_update_vectorized'] = {
    'formula': 'posterior[i] = prior[i] * likelihood[i] / sum(prior[j] * likelihood[j] for j)',
    'description': 'Vectorized Bayesian update for discrete hypotheses.',
    'parameters': {'prior': 'array of prior probabilities', 'likelihood': 'array of likelihoods'},
    'python': 'lambda prior, likelihood: [p * l / sum(pi * li for pi, li in zip(prior, likelihood)) for p, l in zip(prior, likelihood)]',
    'usage': 'Fast belief updating for multiple hypotheses simultaneously.',
    'category': 'probability',
    'importance': 5,
}
MATH_FORMULAS['softmax'] = {
    'formula': 'softmax(x_i) = exp(x_i) / sum(exp(x_j) for j)',
    'description': 'Softmax — convert logits to probability distribution.',
    'parameters': {'x': 'logits vector'},
    'python': 'lambda x: [math.exp(xi - max(x)) / sum(math.exp(xj - max(x)) for xj in x) for xi in x]',
    'usage': 'Output layer for classification, attention weights, policy selection.',
    'category': 'probability',
    'importance': 5,
}
MATH_FORMULAS['sigmoid'] = {
    'formula': 'sigma(x) = 1 / (1 + exp(-x))',
    'description': 'Sigmoid function — squashes input to (0, 1).',
    'parameters': {'x': 'input value'},
    'python': 'lambda x: 1.0 / (1.0 + math.exp(-x)) if x > -700 else 0.0',
    'usage': 'Binary classification, gating, attention, memory gates.',
    'category': 'probability',
    'importance': 5,
}

